// GET /api/tracker-client/:token/fetch-sitemap — fetch URLs from sitemap
app.get('/api/tracker-client/:token/fetch-sitemap', async (req, res) => {
  try {
    const cr = await pool.query('SELECT domain FROM tracker_clients WHERE token=$1 AND (status IS NULL OR status != $2)', [req.params.token, 'deleted']);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    const sitemapUrl = req.query.url;
    if (!sitemapUrl) return res.status(400).json({ success: false, error: 'URL required' });
    const ctrl = new AbortController();
    setTimeout(() => ctrl.abort(), 10000);
    const r = await fetch(sitemapUrl, { headers: { 'User-Agent': 'ContentScale-Bot/1.0' }, signal: ctrl.signal });
    if (!r.ok) return res.status(400).json({ success: false, error: 'Could not fetch sitemap: HTTP ' + r.status });
    const xml = await r.text();
    let urls = [];
    if (/<sitemapindex/i.test(xml)) {
      // Sitemap INDEX — follow each sub-sitemap and collect real page URLs
      const subSitemaps = [...xml.matchAll(/<loc>(https?:\/\/[^<]+\.xml[^<]*)<\/loc>/gi)].map(m => m[1].trim()).slice(0, 20);
      for (const sm of subSitemaps) {
        try {
          const ctrl2 = new AbortController();
          setTimeout(() => ctrl2.abort(), 10000);
          const sr = await fetch(sm, { headers: { 'User-Agent': 'ContentScale-Bot/1.0' }, signal: ctrl2.signal });
          if (!sr.ok) continue;
          const sx = await sr.text();
          const subUrls = [...sx.matchAll(/<loc>(https?:\/\/[^<]+)<\/loc>/gi)].map(m => m[1].trim()).filter(u => !/\.xml(\?|$)/i.test(u));
          urls.push(...subUrls);
        } catch(e) {}
        if (urls.length >= 100) break;
      }
    } else {
      // Regular sitemap — extract page URLs, never the .xml files themselves
      urls = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map(m => m[1].trim()).filter(u => u.startsWith('http') && !/\.xml(\?|$)/i.test(u));
    }
    // Skip non-content archive URLs (WordPress categories, tags, author pages, pagination, feeds, media)
    const _SKIP_ARCHIVE = /\/(category|categories|tag|tags|author|authors|uncategorized)(\/|$)|\/page\/\d+|\/feed\/?$|\/wp-(json|admin|content|includes)\//i;
    const _SKIP_FILE = /\.(jpg|jpeg|png|gif|webp|svg|css|js|pdf|xml|json)(\?|$)/i;
    urls = urls.filter(u => !_SKIP_ARCHIVE.test(u) && !_SKIP_FILE.test(u));
    urls = urls.slice(0, 100);
    // Remember the sitemap URL on the client (shows the "added" check + lets briefs use it for internal links)
    if (urls.length) { try { await pool.query('UPDATE tracker_clients SET sitemap_url=$1 WHERE token=$2', [sitemapUrl, req.params.token]); } catch(e){} }
    res.json({ success: true, urls, count: urls.length });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// PATCH /api/tracker-client/:token/pages/:pageId/html — update html_content + keyword
// POST /api/tracker-client/:token/sitemap-links — internal linking analysis
app.post('/api/tracker-client/:token/sitemap-links', async (req, res) => {
  try {
    const cr = await pool.query('SELECT * FROM tracker_clients WHERE token=$1', [req.params.token]);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    const client = cr.rows[0];
    const { sitemap_url } = req.body;
    if (!sitemap_url) return res.status(400).json({ success: false, error: 'sitemap_url required' });
    try { await pool.query('UPDATE tracker_clients SET sitemap_url=$1 WHERE id=$2', [sitemap_url, client.id]); } catch(e){}

    // Fetch sitemap
    const sitemapResp = await fetch(sitemap_url, { headers: {'User-Agent':'Mozilla/5.0'}, signal: AbortSignal.timeout(10000) });
    if (!sitemapResp.ok) return res.status(400).json({ success: false, error: 'Could not fetch sitemap: ' + sitemapResp.status });
    const sitemapXml = await sitemapResp.text();

    // Extract URLs from sitemap
    const urlMatches = sitemapXml.match(/<loc>(.*?)<\/loc>/g) || [];
    const sitemapPages = urlMatches
      .map(m => m.replace(/<\/?loc>/g, '').trim())
      .filter(u => u.startsWith('http'))
      .slice(0, 100); // max 100 pages

    // Get tracked pages for this client
    const trackedR = await pool.query('SELECT url, keyword FROM tracker_pages WHERE tracker_client_id=$1 AND (is_active=TRUE OR is_active IS NULL)', [client.id]);
    const trackedPages = trackedR.rows;

    if (!trackedPages.length) return res.json({ success: true, pages: sitemapPages, suggestions: [], ai_prompt: '', message: 'No tracked pages yet. Add pages to tracker first.' });

    // Build context for Gemini
    const geminiKey = process.env.GEMINI_API_KEY;
    if (!geminiKey) return res.json({ success: true, pages: sitemapPages, suggestions: [], ai_prompt: buildLinkPrompt(trackedPages, sitemapPages) });

    const prompt = `You are an internal linking specialist. Analyse this website's pages and suggest missing internal links.

TRACKED PAGES (pages I want to improve):
${trackedPages.map((p, i) => `${i+1}. ${p.url} [keyword: ${p.keyword || 'unknown'}]`).join('\n')}

ALL PAGES ON SITE (from sitemap):
${sitemapPages.slice(0, 50).join('\n')}

TASK: For each tracked page, suggest 1-3 pages from the sitemap it should link TO (one-directional: tracked page → sitemap page).
Only suggest links that make topical sense. Do NOT suggest linking back.

Return ONLY a JSON array:
[{
  "from_page": "tracked page URL",
  "to_page": "sitemap page URL to link to",
  "anchor_text": "exact anchor text (3-6 words, natural)",
  "where_to_add": "brief description of where in the content",
  "priority": "high|medium|low",
  "reason": "one sentence why this link helps"
}]`;

    const gResp = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${geminiKey}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0.3, maxOutputTokens: 1000 } })
    });

    let suggestions = [];
    if (gResp.ok) {
      const gData = await gResp.json();
      const gText = gData.candidates?.[0]?.content?.parts?.[0]?.text || '';
      try { suggestions = JSON.parse(gText.replace(/```json|```/g, '').trim()); } catch(e) { suggestions = []; }
    }

    const aiPrompt = buildLinkPrompt(trackedPages, sitemapPages);
    res.json({ success: true, pages: sitemapPages, suggestions, ai_prompt: aiPrompt });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

function buildLinkPrompt(trackedPages, sitemapPages) {
  return `I have a website and want to improve internal linking. Here are the pages I want to add links FROM:\n\n${trackedPages.map(p => '- ' + p.url + (p.keyword ? ' (keyword: ' + p.keyword + ')' : '')).join('\n')}\n\nAll pages on my site:\n${sitemapPages.slice(0,50).join('\n')}\n\nFor each page I track, suggest 2-3 internal links I should ADD to that page, pointing to relevant other pages on my site. Give exact anchor text and where in the content to add each link. Focus on topically related pages only.`;
}

// PATCH /api/tracker-client/:token/settings — update client whatsapp + callmebot_key
app.patch('/api/tracker-client/:token/settings', async (req, res) => {
  try {
    const cr = await pool.query('SELECT id FROM tracker_clients WHERE token=$1 AND (status IS NULL OR status != $2)', [req.params.token, 'deleted']);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    const { whatsapp, callmebot_key, name, brand_context } = req.body;
    const updates = []; const vals = []; let i = 1;
    if (whatsapp !== undefined) { updates.push(`whatsapp=$${i++}`); vals.push(whatsapp || null); }
    if (callmebot_key !== undefined) { updates.push(`callmebot_key=$${i++}`); vals.push(callmebot_key || null); }
    if (name !== undefined) { updates.push(`name=$${i++}`); vals.push(name || null); }
    if (brand_context !== undefined) { updates.push(`brand_context=$${i++}`); vals.push((brand_context || '').slice(0, 4000)); }
    if (!updates.length) return res.json({ success: true });
    vals.push(cr.rows[0].id);
    await pool.query(`UPDATE tracker_clients SET ${updates.join(',')} WHERE id=$${i}`, vals);
    res.json({ success: true });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/tracker-client/:token/pages/:pageId/html', async (req, res) => {
  try {
    const cr = await pool.query('SELECT id FROM tracker_clients WHERE token=$1 AND (status IS NULL OR status != $2)', [req.params.token, 'deleted']);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    const own = await pool.query('SELECT id FROM tracker_pages WHERE id=$1 AND tracker_client_id=$2', [req.params.pageId, cr.rows[0].id]);
    if (!own.rows.length) return res.status(403).json({ success: false, error: 'Not your page' });
    const { html_content, keyword } = req.body;

    // Ensure columns exist
    await pool.query('ALTER TABLE tracker_pages ADD COLUMN IF NOT EXISTS html_pasted_at TIMESTAMPTZ').catch(()=>{});
    await pool.query('ALTER TABLE tracker_pages ADD COLUMN IF NOT EXISTS html_source TEXT').catch(()=>{});
    await pool.query('ALTER TABLE tracker_pages ADD COLUMN IF NOT EXISTS needs_html BOOLEAN DEFAULT FALSE').catch(()=>{});

    // Build update
    const fields = ['html_source=$1', 'needs_html=FALSE', 'is_done=FALSE', 'html_pasted_at=NOW()'];
    const vals = ['manual'];
    if (html_content) { fields.push(`html_content=$${vals.length+1}`); vals.push(html_content.substring(0,500000)); }
    if (keyword) { fields.push(`keyword=$${vals.length+1}`); vals.push(keyword.trim()); }
    // Has this page been scanned before? First HTML → scan now; later HTML → wait for the scheduled auto-check
    const prevR = await pool.query('SELECT last_checked_at, brief_check_count, next_check_at FROM tracker_pages WHERE id=$1', [req.params.pageId]);
    const prev = prevR.rows[0] || {};
    const wasScanned = !!prev.last_checked_at || (parseInt(prev.brief_check_count) || 0) > 0;

    vals.push(req.params.pageId);
    await pool.query(`UPDATE tracker_pages SET ${fields.join(',')} WHERE id=$${vals.length}`, vals);

    if (!wasScanned) {
      res.json({ success: true, scanning: true });
      _triggerPageScan(parseInt(req.params.pageId), 1000);
    } else {
      res.json({ success: true, scanning: false, next_check_at: prev.next_check_at });
    }
  } catch(e) {
    console.error('[html-patch]', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

