// POST /api/tracker-client/:token/cleanup — remove non-content/non-live pages; keep only live pages in sitemap or GSC
app.post('/api/tracker-client/:token/cleanup', async (req, res) => {
  try {
    const cr = await pool.query('SELECT id, sitemap_url FROM tracker_clients WHERE token=$1', [req.params.token]);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    const client = cr.rows[0];

    const FILE = /\.(jpg|jpeg|png|gif|webp|svg|css|js|pdf|xml|json|ico|mp4|webm|woff2?|ttf|eot)(\?|$)/i;
    const ARCHIVE = /\/(category|categories|tag|tags|author|authors|uncategorized)(\/|$)|\/page\/\d+|\/feed\/?$|\/wp-(json|admin|content|includes)\//i;
    const norm = u => String(u||'').trim().replace(/\/$/, '').toLowerCase();

    // Build the sitemap URL set (best-effort; follows a sitemap index)
    const sitemapSet = new Set();
    let sitemapLoaded = false;
    if (client.sitemap_url) {
      try {
        const grab = async (sm, depth) => {
          if (depth > 2) return;
          const r = await fetch(sm, { headers: {'User-Agent':'Mozilla/5.0'}, signal: AbortSignal.timeout(10000) });
          if (!r.ok) return;
          const xml = await r.text();
          const locs = [...xml.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/gi)].map(m => m[1].trim());
          locs.filter(u => /^https?:\/\//i.test(u) && !/\.xml(\?|$)/i.test(u)).forEach(u => sitemapSet.add(norm(u)));
          const subs = locs.filter(u => /\.xml(\?|$)/i.test(u)).slice(0, 25);
          for (const s of subs) { try { await grab(s, depth + 1); } catch(e){} }
        };
        await grab(client.sitemap_url, 0);
        sitemapLoaded = sitemapSet.size > 0;
      } catch(e) {}
    }

    const pr = await pool.query(
      `SELECT id, url, gsc_clicks, gsc_impressions, gsc_position, gsc_keyword
       FROM tracker_pages WHERE tracker_client_id=$1 AND (is_active=TRUE OR is_active IS NULL)`,
      [client.id]
    );

    const removeIds = []; const removedUrls = []; let kept = 0;
    for (const p of pr.rows) {
      const url = p.url || '';
      const isJunk = FILE.test(url) || ARCHIVE.test(url);
      const hasGsc = (p.gsc_clicks != null) || (p.gsc_impressions != null) || (p.gsc_position != null) || !!p.gsc_keyword;
      const inSitemap = sitemapSet.has(norm(url));
      let remove;
      if (isJunk) {
        remove = true;                       // .jpg, /category/, feeds, etc. — always remove
      } else if (sitemapLoaded || hasGsc) {
        remove = !(inSitemap || hasGsc);     // keep only live pages in sitemap or GSC
      } else {
        remove = false;                      // no sitemap + no GSC to check against -> only strip obvious junk
      }
      if (remove) { removeIds.push(p.id); if (removedUrls.length < 60) removedUrls.push(url); }
      else kept++;
    }

    if (removeIds.length) {
      await pool.query('UPDATE tracker_pages SET is_active=FALSE WHERE id=ANY($1) AND tracker_client_id=$2', [removeIds, client.id]);
    }
    res.json({ success: true, removed: removeIds.length, kept, sitemap_used: sitemapLoaded, removed_urls: removedUrls });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// POST /api/tracker-client/:token/reset-scans — clear scan data (snapshots, score, citations, dates); pages return to "not scanned yet". Keeps URLs + keywords + GSC data.
app.post('/api/tracker-client/:token/reset-scans', async (req, res) => {
  try {
    const cr = await pool.query('SELECT id FROM tracker_clients WHERE token=$1', [req.params.token]);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    const clientId = cr.rows[0].id;
    const { page_ids } = req.body || {};

    let idsRow;
    if (Array.isArray(page_ids) && page_ids.length) {
      idsRow = await pool.query('SELECT id FROM tracker_pages WHERE id=ANY($1) AND tracker_client_id=$2', [page_ids, clientId]);
    } else {
      idsRow = await pool.query('SELECT id FROM tracker_pages WHERE tracker_client_id=$1', [clientId]);
    }
    const ids = idsRow.rows.map(r => r.id);
    if (!ids.length) return res.json({ success: true, reset: 0 });

    await pool.query('DELETE FROM tracker_snapshots WHERE page_id = ANY($1)', [ids]).catch(()=>{});
    // Null each scan field separately so a non-existent column can't block clearing the others (esp. the Checked/Next dates)
    for (const col of ['last_checked','last_checked_at','next_check_at','graaf_score','brief_started_at','brief_content','needs_html','content_hash','last_page_hash','html_pasted_at','html_source','has_html_content','ai_google_overview_cited','ai_perplexity_cited','ai_bing_cited','ai_brave_cited']) {
      await pool.query(`UPDATE tracker_pages SET ${col}=NULL WHERE id = ANY($1)`, [ids]).catch(()=>{});
    }
    await pool.query('UPDATE tracker_pages SET brief_check_count=0 WHERE id = ANY($1)', [ids]).catch(()=>{});

    res.json({ success: true, reset: ids.length });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// POST /api/tracker-client/:token/scan-all — scan all pages one by one
app.post('/api/tracker-client/:token/scan-all', async (req, res) => {
  try {
    const cr = await pool.query('SELECT id FROM tracker_clients WHERE token=$1', [req.params.token]);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    const unscannedOnly = req.body && req.body.unscanned_only === true;
    let pages;
    if (unscannedOnly) {
      pages = await pool.query(`
        SELECT p.* FROM tracker_pages p
        LEFT JOIN tracker_snapshots s ON s.page_id = p.id
        WHERE p.tracker_client_id=$1 AND (p.is_active=TRUE OR p.is_active IS NULL)
        AND s.id IS NULL
        ORDER BY p.created_at ASC
      `, [cr.rows[0].id]);
    } else {
      pages = await pool.query('SELECT * FROM tracker_pages WHERE tracker_client_id=$1 AND (is_active=TRUE OR is_active IS NULL) ORDER BY created_at ASC', [cr.rows[0].id]);
    }

    res.json({ success: true, queued: pages.rows.length, message: 'Scanning ' + pages.rows.length + ' ' + (unscannedOnly ? 'unscanned ' : '') + 'pages one by one (~' + Math.ceil(pages.rows.length * 3 / 60) + ' min)' });

    const checkKeys = {
      serpapiKey:    process.env.SERPAPI_KEY || process.env.SERPER_API_KEY,
      perplexityKey: process.env.PERPLEXITY_API_KEY,
      braveKey:      process.env.BRAVE_SEARCH_API_KEY,
      youKey:        process.env.YOU_API_KEY
    };
    for (let i = 0; i < pages.rows.length; i++) {
      await new Promise(r => setTimeout(r, i === 0 ? 100 : 3000));
      console.log('[scan-all] scanning page', i+1, '/', pages.rows.length, pages.rows[i].url);
      runTrackerCheck(pages.rows[i], process.env.GEMINI_API_KEY, checkKeys, true)
        .catch(e => console.warn('[scan-all] page', pages.rows[i].id, e.message));
    }
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// PATCH /api/tracker-client/:token/pages/:pageId/done — mark page done/undone
app.patch('/api/tracker-client/:token/pages/:pageId/done', async (req, res) => {
  try {
    const cr = await pool.query('SELECT id FROM tracker_clients WHERE token=$1 AND (status IS NULL OR status != $2)', [req.params.token, 'deleted']);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    const own = await pool.query('SELECT id FROM tracker_pages WHERE id=$1 AND tracker_client_id=$2', [req.params.pageId, cr.rows[0].id]);
    if (!own.rows.length) return res.status(403).json({ success: false, error: 'Not your page' });
    const { is_done } = req.body;
    if (is_done) {
      // Done pressed — reset brief + flag that new HTML is needed
      await pool.query(
        `UPDATE tracker_pages SET is_done=TRUE, brief_done_at=NOW(), needs_html=TRUE WHERE id=$1`,
        [req.params.pageId]
      );
      res.json({ success: true });

      // Send reminder email + WhatsApp after done
      setImmediate(async () => {
        try {
          const clientR = await pool.query('SELECT * FROM tracker_clients WHERE id=$1', [cr.rows[0].id]);
          const pageR = await pool.query('SELECT url FROM tracker_pages WHERE id=$1', [req.params.pageId]);
          const client = clientR.rows[0];
          const pageUrl = pageR.rows[0]?.url || '';
          const trackerUrl = (process.env.APP_URL || 'https://app.contentscale.site') + '/track/' + client.token;

          // Email reminder
          if (client.email) {
            const subject = 'Action needed: paste your updated HTML — ' + (client.domain || pageUrl);
            const htmlBody = '<h2 style="font-size:17px;font-weight:800;color:#0f172a;margin-bottom:10px;">Great — Done pressed! One more step.</h2>'
              + '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:14px;">You marked your implementation as done. Now the system needs the <strong>updated HTML of your page</strong> to measure the improvements you just made and start the next Citation Brief cycle.</p>'
              + '<div style="background:#fefce8;border:1px solid #fde047;border-radius:8px;padding:14px 16px;margin-bottom:16px;">'
              + '<div style="font-size:12px;font-weight:700;color:#854d0e;margin-bottom:6px;">&#9888; Required: paste new HTML</div>'
              + '<div style="font-size:13px;color:#854d0e;line-height:1.6;">1. Open <strong>' + pageUrl + '</strong> in Chrome<br>2. Right-click &rarr; View Page Source<br>3. Ctrl+A &rarr; Ctrl+C<br>4. Go to your tracker &rarr; click <strong>Paste new HTML</strong></div>'
              + '</div>'
              + '<a href="' + trackerUrl + '" style="display:inline-block;background:#7c3aed;color:white;text-decoration:none;padding:10px 22px;border-radius:6px;font-size:13px;font-weight:700;">Open tracker &rarr;</a>'
              + '<p style="font-size:11px;color:#94a3b8;margin-top:14px;">Without the new HTML, the system cannot measure your improvements or generate the next Citation Brief.</p>';
            // Get telegram for done reminder
            const doneClientR = await pool.query('SELECT telegram_chat_id FROM tracker_clients WHERE id=$1', [cr.rows[0].id]);
            const doneTgId = doneClientR.rows[0]?.telegram_chat_id;
            if (doneTgId) await sendTelegramNotification(doneTgId, '⚠️ <b>Action needed:</b> Paste your updated HTML in the tracker to continue your Citation Brief cycle.\n\n<a href="' + trackerUrl + '">Open tracker →</a>').catch(()=>{});
            await sendTrackerEmail(cr.rows[0].id, subject, htmlBody);
          }

          // Telegram reminder
          if (client.telegram_chat_id) {
            await sendTelegramNotification(client.telegram_chat_id, '✅ <b>Done pressed!</b> Now paste the updated HTML in your tracker so the system can measure your improvements.\n\n<a href="' + trackerUrl + '">Open tracker →</a>');
          }
        } catch(e) { console.warn('[done-reminder]', e.message); }
      });
    } else {
      // Undone — just clear is_done flag
      await pool.query('UPDATE tracker_pages SET is_done=FALSE, needs_html=FALSE WHERE id=$1', [req.params.pageId]);
      res.json({ success: true });
    }
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

