// POST /api/tracker-client/:token/live-events — internal: save brief after check
const _clientDomainCache = new Map(); // token -> { domain, exp } — avoids a DB hit on every poll
app.get('/api/tracker-client/:token/live-events', async (req, res) => {
  try {
    const token = req.params.token;
    let domain;
    const cached = _clientDomainCache.get(token);
    if (cached && cached.exp > Date.now()) {
      domain = cached.domain;
    } else {
      const cr = await pool.query('SELECT domain FROM tracker_clients WHERE token=$1 AND (status IS NULL OR status != $2)', [token, 'deleted']);
      if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
      domain = cr.rows[0].domain;
      _clientDomainCache.set(token, { domain: domain, exp: Date.now() + 300000 }); // cache 5 min
    }
    const since = req.query.since ? new Date(req.query.since).getTime() : Date.now() - 60000;
    // Filter events relevant to this domain
    const events = _liveEvents.filter(function(e) {
      if (new Date(e.ts||0).getTime() <= since) return false;
      if (e.type === 'news') return true; // show news to everyone
      const url = e.url || e.page_url || '';
      return url.includes(domain);
    }).slice(0, 15);
    res.json({ success: true, events, ts: new Date().toISOString(), domain });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// ── Latest briefs for a client — lets the Live Wall populate on open ─────────
app.get('/api/tracker-client/:token/latest-briefs', async (req, res) => {
  try {
    const cr = await pool.query('SELECT id FROM tracker_clients WHERE token=$1 AND (status IS NULL OR status != $2)', [req.params.token, 'deleted']);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    const r = await pool.query(
      `SELECT p.url, p.keyword, p.gsc_keyword, p.brief_content, p.gsc_clicks, p.gsc_impressions, p.gsc_position,
              s.checked_at, s.google_position, s.ai_google_overview_cited, s.ai_perplexity_cited, s.ai_bing_cited, s.ai_brave_cited,
              s.score, s.recommendations, s.gsc_brief, s.source_suggestions
       FROM tracker_pages p
       LEFT JOIN LATERAL (
         SELECT * FROM tracker_snapshots WHERE page_id = p.id ORDER BY checked_at DESC LIMIT 1
       ) s ON true
       WHERE p.tracker_client_id = $1 AND (p.is_active IS NULL OR p.is_active = TRUE)
       ORDER BY s.checked_at DESC NULLS LAST LIMIT 8`,
      [cr.rows[0].id]
    );
    function _arr(v) { if (Array.isArray(v)) return v; if (!v) return []; try { var x = typeof v === 'string' ? JSON.parse(v) : v; return Array.isArray(x) ? x : (Array.isArray(x.items) ? x.items : []); } catch(e) { return []; } }
    const briefs = r.rows.map(function(p) {
      let bc = {};
      try { bc = typeof p.brief_content === 'string' ? JSON.parse(p.brief_content) : (p.brief_content || {}); } catch(e) { bc = {}; }
      // Prefer the stored brief; fall back to the latest snapshot so the wall fills without a rescan
      let items = Array.isArray(bc.items) ? bc.items : [];
      if (!items.length) items = _arr(p.recommendations);
      let gscB = Array.isArray(bc.gsc_brief) ? bc.gsc_brief : [];
      if (!gscB.length) gscB = _arr(p.gsc_brief);
      let srcB = Array.isArray(bc.source_suggestions) ? bc.source_suggestions : [];
      if (!srcB.length) srcB = _arr(p.source_suggestions);
      return {
        type: 'brief_ready',
        url: p.url,
        keyword: p.keyword || p.gsc_keyword || '',
        position: bc.position != null ? bc.position : p.google_position,
        aio_cited: bc.aio != null ? bc.aio : p.ai_google_overview_cited,
        perp_cited: bc.perp != null ? bc.perp : p.ai_perplexity_cited,
        bing_cited: bc.bing_cited != null ? bc.bing_cited : p.ai_bing_cited,
        brave_cited: bc.brave_cited != null ? bc.brave_cited : p.ai_brave_cited,
        score: bc.score != null ? bc.score : p.score,
        passages: items,
        gsc_brief: gscB,
        source_suggestions: srcB,
        gsc_clicks: p.gsc_clicks, gsc_impressions: p.gsc_impressions, gsc_position: p.gsc_position,
        ts: p.checked_at ? new Date(p.checked_at).toISOString() : ''
      };
    }).filter(function(b) { return b.passages.length || b.position != null || b.score != null; });
    res.json({ success: true, briefs });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// ── Scan queue — max 1 concurrent scan ───────────────────────────────────────
const _scanQueue = [];
let _scanRunning = false;

function _processScanQueue() {
  if (_scanRunning || _scanQueue.length === 0) return;
  _scanRunning = true;
  const pageId = _scanQueue.shift();
  pool.query('SELECT * FROM tracker_pages WHERE id=$1 AND (is_active=TRUE OR is_active IS NULL)', [pageId])
    .then(function(r) {
      if (!r.rows.length) { _scanRunning = false; setTimeout(_processScanQueue, 500); return; }
      const pg = r.rows[0];
      const pgId = pg.id;
      const ex = _trackerCheckStatus.get(pgId);
      if (ex && ex.running) { _scanRunning = false; setTimeout(_processScanQueue, 500); return; }
      _trackerCheckStatus.set(pgId, { running: true, steps: [], startedAt: new Date().toISOString(), finishedAt: null, url: pg.url });
      const pgDomain = (pg.url||'').replace(/^https?:\/\//, '').split('/')[0];
      _sseBroadcast({ type: 'check_start', pageId: pgId, domain: pgDomain, url: pg.url, keyword: pg.keyword || pg.gsc_keyword || '', ts: new Date().toISOString() });
      console.log('[tracker] _triggerPageScan:', pgId, pg.url);
      const keys = { serpapiKey: process.env.SERPAPI_KEY || process.env.SERPER_API_KEY, perplexityKey: process.env.PERPLEXITY_API_KEY, braveKey: process.env.BRAVE_SEARCH_API_KEY, youKey: process.env.YOU_API_KEY };
      setImmediate(async () => {
        try { await Promise.race([
          runTrackerCheck(pg, process.env.GEMINI_API_KEY, keys, true),
          new Promise(function(_, rej){ setTimeout(function(){ rej(new Error('scan watchdog timeout (150s)')); }, 150000); })
        ]); }
        catch(e) { console.warn('[trigger-scan]', e.message); }
        finally {
          const st = _trackerCheckStatus.get(pgId);
          if (st) { st.running = false; st.finishedAt = new Date().toISOString(); }
          _sseBroadcast({ type: 'check_done', pageId: pgId, domain: pgDomain, url: pg.url, ts: new Date().toISOString() });
          _scanRunning = false;
          setTimeout(_processScanQueue, 2000); // 2s between scans
        }
      });
    }).catch(e => { console.warn('[trigger-scan-query]', e.message); _scanRunning = false; setTimeout(_processScanQueue, 500); });
}

// ── Helper: trigger a scan for a tracker page by ID ──────────────────────────
function _triggerPageScan(pageId, delayMs) {
  delayMs = delayMs || 500;
  setTimeout(function() {
    if (!_scanQueue.includes(pageId)) _scanQueue.push(pageId);
    _processScanQueue();
  }, delayMs);
}

// POST /api/tracker-client/:token/pages — add URL to track
app.post('/api/tracker-client/:token/pages', async (req, res) => {
  try {
    const cr = await pool.query('SELECT * FROM tracker_clients WHERE token=$1 AND (status IS NULL OR status != $2)', [req.params.token, 'deleted']);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    const client = cr.rows[0];

    // Check total page limit across all domains for this client
    const countR = await pool.query(
      `SELECT COUNT(*) FROM tracker_pages WHERE tracker_client_id=$1 AND (is_active=TRUE OR is_active IS NULL)`,
      [client.id]
    );
    const count = parseInt(countR.rows[0].count);
    const maxPages = client.max_pages || 3;
    if (count >= maxPages) return res.status(400).json({ success: false, error: `Tracker limit reached: ${count}/${maxPages} pages used. Contact Ottmar to upgrade your plan.` });

    const { url, keyword, gsc_clicks, gsc_impressions, gsc_position, gsc_ctr, gsc_keyword } = req.body;
    if (!url) return res.status(400).json({ success: false, error: 'URL required' });

    // Verify URL belongs to client domain or its subdomains (or admin-added extra domains)
    const urlDomain = url.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].toLowerCase().split(':')[0];
    const allowedDomains = [client.domain, ...(client.extra_domains || '').split(',').map(d => d.trim().replace(/^www\./, '')).filter(Boolean)];
    const domainOk = allowedDomains.some(d => {
      const clean = d.toLowerCase().replace(/^www\./, '');
      return urlDomain === clean || urlDomain.endsWith('.' + clean);
    });
    if (!domainOk) {
      return res.json({ success: false, skipped: true, error: `URL skipped — belongs to different domain` });
    }

    // Check duplicate — normalize URL to match all variants
    const normalUrl = url.replace(/\/$/, ''); // strip trailing slash
    const dupR = await pool.query(
      `SELECT id FROM tracker_pages WHERE tracker_client_id=$1 AND (url=$2 OR url=$3 OR url=$4 OR url=$5)`,
      [client.id, url, normalUrl, normalUrl + '/', url.replace(/^https?:\/\/www\./, 'https://')]
    );
    if (dupR.rows.length) {
      const pageId = dupR.rows[0].id;
      const updates = [];
      const vals = [];
      let i = 1;
      if (gsc_clicks !== undefined && gsc_clicks !== null) { updates.push(`gsc_clicks=$${i++}`); vals.push(gsc_clicks); }
      if (gsc_impressions !== undefined && gsc_impressions !== null) { updates.push(`gsc_impressions=$${i++}`); vals.push(gsc_impressions); }
      if (gsc_position !== undefined && gsc_position !== null) { updates.push(`gsc_position=$${i++}`); vals.push(gsc_position); }
      if (gsc_ctr !== undefined && gsc_ctr !== null) { updates.push(`gsc_ctr=$${i++}`); vals.push(gsc_ctr); }
      if (gsc_keyword) { updates.push(`gsc_keyword=$${i++}`); vals.push(gsc_keyword); }
      if (keyword && !gsc_keyword) { updates.push(`keyword=COALESCE(keyword,$${i++})`); vals.push(keyword); }
      if (updates.length) {
        vals.push(pageId);
        await pool.query(`UPDATE tracker_pages SET ${updates.join(',')} WHERE id=$${i}`, vals).catch(()=>{});
      }
      res.json({ success: true, page_id: pageId, updated: true });
      return;
    }

    let pr;
    try {
      pr = await pool.query(
        `INSERT INTO tracker_pages (tracker_client_id, url, keyword, gsc_clicks, gsc_impressions, gsc_position, gsc_ctr, gsc_keyword, check_frequency, next_check_at, is_active)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8,'3days',NULL,TRUE)
         RETURNING id`,
        [client.id, url, keyword||null, gsc_clicks||null, gsc_impressions||null, gsc_position||null, gsc_ctr||null, gsc_keyword||null]
      );
    } catch(insertErr) {
      console.error('[add-page] insert error:', insertErr.message);
      try {
        pr = await pool.query(
          `INSERT INTO tracker_pages (tracker_client_id, url, keyword, check_frequency, next_check_at, is_active)
           VALUES ($1,$2,$3,'3days',NULL,TRUE)
           RETURNING id`,
          [client.id, url, keyword||null]
        );
      } catch(e2) {
        console.error('[add-page] fallback insert error:', e2.message);
        return res.status(500).json({ success: false, error: e2.message });
      }
    }

    if (!pr || !pr.rows || !pr.rows.length) {
      return res.status(500).json({ success: false, error: 'Insert returned no row' });
    }

    const newPageId = pr.rows[0].id;
    res.json({ success: true, page_id: newPageId, remaining: maxPages - count - 1 });

    // No auto-scan on add: a page is only scanned when the user explicitly scans it
    // (clicks Scan, Scan All, or pastes HTML). The first manual scan starts the 3-day schedule.
  } catch(e) {
    console.error('[POST tracker pages]', e.message, e.detail || '');
    res.status(500).json({ success: false, error: e.message, detail: e.detail || null });
  }
});

// POST /api/tracker-client/:token/refresh-gsc — refresh GSC data for all pages
app.post('/api/tracker-client/:token/refresh-gsc', async (req, res) => {
  try {
    const cr = await pool.query('SELECT * FROM tracker_clients WHERE token=$1', [req.params.token]);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    if (!cr.rows[0].gsc_enabled) return res.status(403).json({ success: false, error: 'GSC not enabled for this tracker' });

    const pages = await pool.query(
      'SELECT id, url FROM tracker_pages WHERE tracker_client_id=$1 AND (is_active=TRUE OR is_active IS NULL)',
      [cr.rows[0].id]
    );

    res.json({ success: true, queued: pages.rows.length, message: 'Refreshing GSC data for ' + pages.rows.length + ' pages' });

    // Background: fetch GSC data for each page
    for (const page of pages.rows) {
      try {
        const gscResp = await fetch((process.env.APP_URL || 'https://app.contentscale.site') + '/api/gsc/auto-fill', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ pageUrl: page.url })
        });
        if (gscResp.ok) {
          const gscData = await gscResp.json();
          if (gscData.success && gscData.data) {
            const d = gscData.data;
            await pool.query(
              `UPDATE tracker_pages SET gsc_clicks=$1, gsc_impressions=$2, gsc_position=$3, gsc_ctr=$4, gsc_keyword=$5 WHERE id=$6`,
              [d.clicks||null, d.impressions||null, d.position||null, d.ctr||null, d.keyword||null, page.id]
            ).catch(()=>{});
          }
        }
        await new Promise(r => setTimeout(r, 500)); // rate limit
      } catch(e) { console.warn('[refresh-gsc] page', page.id, e.message); }
    }
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// GET /api/tracker-client/:token/debug-pages — check what data exists per page
app.get('/api/tracker-client/:token/debug-pages', async (req, res) => {
  try {
    const cr = await pool.query('SELECT id FROM tracker_clients WHERE token=$1', [req.params.token]);
    if (!cr.rows.length) return res.status(404).json({ error: 'Not found' });
    const r = await pool.query(`
      SELECT p.id, p.url, p.keyword, p.last_checked_at, p.brief_check_count,
             p.gsc_clicks, p.gsc_impressions, p.gsc_position, p.gsc_keyword,
             s.checked_at as snap_checked_at, s.google_position as snap_pos,
             s.ai_google_overview_cited, s.ai_perplexity_cited,
             s.score as snap_score
      FROM tracker_pages p
      LEFT JOIN LATERAL (
        SELECT * FROM tracker_snapshots WHERE page_id = p.id ORDER BY checked_at DESC LIMIT 1
      ) s ON true
      WHERE p.tracker_client_id=$1 AND (p.is_active=TRUE OR p.is_active IS NULL)
      ORDER BY p.id ASC LIMIT 10
    `, [cr.rows[0].id]);
    res.json({ success: true, pages: r.rows });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// POST /api/tracker-client/:token/merge-pages — merge duplicate URLs, keep best
app.post('/api/tracker-client/:token/merge-pages', async (req, res) => {
  try {
    const cr = await pool.query('SELECT id FROM tracker_clients WHERE token=$1', [req.params.token]);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    const clientId = cr.rows[0].id;

    // Get all active pages — simplest possible query
    const pagesR = await pool.query(
      'SELECT id, url FROM tracker_pages WHERE tracker_client_id=$1 AND is_active=TRUE ORDER BY id ASC',
      [clientId]
    );

    const seen = {};
    let merged = 0;
    for (const p of pagesR.rows) {
      const norm = (p.url||'').toLowerCase()
        .replace(/^https?:\/\//,'').replace(/^www\./,'')
        .replace(/\/$/,'').split('?')[0].split('#')[0];
      if (seen[norm]) {
        await pool.query('UPDATE tracker_pages SET is_active=FALSE WHERE id=$1', [p.id]);
        merged++;
      } else {
        seen[norm] = p.id;
      }
    }
    res.json({ success: true, merged, kept: Object.keys(seen).length });
  } catch(e) {
    console.error('[merge-pages] ERROR:', e.message, e.stack);
    res.status(500).json({ success: false, error: e.message });
  }
});

// POST /api/tracker-client/:token/clean-pages — remove image/asset URLs
app.post('/api/tracker-client/:token/clean-pages', async (req, res) => {
  try {
    const cr = await pool.query('SELECT id FROM tracker_clients WHERE token=$1', [req.params.token]);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    const clientId = cr.rows[0].id;
    const pagesR = await pool.query('SELECT id, url FROM tracker_pages WHERE tracker_client_id=$1 AND (is_active=TRUE OR is_active IS NULL)', [clientId]);
    const badExt = ['.jpg','.jpeg','.png','.gif','.webp','.svg','.ico','.pdf','.zip','.mp4','.mp3','.wav','.css','.js','.woff','.woff2','.ttf','.eot','.xml'];
    const badPat = ['wp-content/uploads','wp-includes','/feed','/amp/','wp-json','?replytocom','xmlrpc.php','/page/2','/page/3'];
    let cleaned = 0;
    for (const row of pagesR.rows) {
      const u = (row.url||'').toLowerCase().split('?')[0];
      const isBadExt = badExt.some(ext => u.endsWith(ext));
      const isBadPat = badPat.some(pat => (row.url||'').toLowerCase().includes(pat));
      if (isBadExt || isBadPat) {
        await pool.query('UPDATE tracker_pages SET is_active=FALSE WHERE id=$1', [row.id]);
        cleaned++;
      }
    }
    res.json({ success: true, cleaned, total: pagesR.rows.length });
  } catch(e) {
    console.error('[clean-pages]', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

// DELETE /api/tracker-client/:token/pages/:pageId
// POST /api/tracker-client/:token/check/:pageId — trigger manual check
app.post('/api/tracker-client/:token/check/:pageId', async (req, res) => {
  try {
    const cr = await pool.query('SELECT id FROM tracker_clients WHERE token=$1 AND (status IS NULL OR status != $2)', [req.params.token, 'deleted']);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    const own = await pool.query('SELECT * FROM tracker_pages WHERE id=$1 AND tracker_client_id=$2', [req.params.pageId, cr.rows[0].id]);
    if (!own.rows.length) return res.status(403).json({ success: false, error: 'Not your page' });
    const page = own.rows[0];
    const pageId = page.id;

    // Block if already running
    const existing = _trackerCheckStatus.get(pageId);
    if (existing && existing.running) return res.json({ success: true, message: 'Already running', page_id: pageId, already_running: true });

    // Initialize status — same as engine route
    _trackerCheckStatus.set(pageId, { running: true, steps: [], startedAt: new Date().toISOString(), finishedAt: null, url: page.url });

    // Broadcast check start to SSE so client UI updates
    const domain = (page.url||'').replace(/^https?:\/\//, '').split('/')[0];
    _sseBroadcast({ type: 'check_start', pageId, domain, url: page.url, keyword: page.keyword || page.gsc_keyword || '', ts: new Date().toISOString() });

    res.json({ success: true, message: 'Check started', page_id: pageId });

    const checkKeys = {
      serpapiKey:    process.env.SERPAPI_KEY || process.env.SERPER_API_KEY,
      perplexityKey: process.env.PERPLEXITY_API_KEY,
      braveKey:      process.env.BRAVE_SEARCH_API_KEY,
      youKey:        process.env.YOU_API_KEY
    };

    setImmediate(async () => {
      try {
        await runTrackerCheck(page, process.env.GEMINI_API_KEY, checkKeys, true);
      } catch(e) {
        console.warn('[client-check]', e.message);
      } finally {
        const st = _trackerCheckStatus.get(pageId);
        if (st) { st.running = false; st.finishedAt = new Date().toISOString(); }
        // Broadcast completion
        try {
          const snap2 = await pool.query(
            `SELECT s.*, p.url, p.keyword, p.gsc_keyword, p.brief_content
             FROM tracker_snapshots s JOIN tracker_pages p ON p.id=s.page_id
             WHERE s.page_id=$1 ORDER BY s.checked_at DESC LIMIT 1`,
            [pageId]
          );
          if (snap2.rows.length) {
            const s = snap2.rows[0];
            _sseBroadcast({
              type: 'check_done',
              pageId,
              domain,
              url: s.url,
              keyword: s.keyword || s.gsc_keyword || '',
              position: s.google_position,
              aio_cited: s.ai_google_overview_cited,
              perp_cited: s.ai_perplexity_cited,
              bing_cited: s.ai_bing_cited,
              brave_cited: s.ai_brave_cited,
              score: s.score,
              ts: new Date().toISOString()
            });
          }
        } catch(e2) { console.warn('[client-check-done]', e2.message); }
      }
    });
  } catch(e) {
    console.error('[client-check]', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});


