app.post('/api/setup/recover-admin', async (req, res) => {
  const { recovery_key, new_password } = req.body;
  const expectedKey = process.env.ADMIN_RECOVERY_KEY || 'contentscale-reset-2024';
  if (recovery_key !== expectedKey) return res.status(403).json({ success: false, error: 'Invalid recovery key' });
  if (!new_password || new_password.length < 6) return res.status(400).json({ success: false, error: 'New password must be at least 6 characters' });
  try {
    const hash = await bcrypt.hash(new_password, 10);
    // Reset the default admin 'ot'
    await pool.query(
      `INSERT INTO super_admins (username, password_hash, is_active, last_login) VALUES ('ot', $1, TRUE, NOW())
       ON CONFLICT (username) DO UPDATE SET password_hash = $1, is_active = TRUE, session_token = NULL, last_login = NOW()`,
      [hash]
    );
    res.json({ success: true, message: 'Admin password reset. Login with: ot / ' + new_password });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});
app.post('/api/setup/verify-admin', async (req, res) => {
const { username, password } = req.body;
if (!pool) return res.status(503).json({ success: false, error: 'DB down' });
try {
let result;
try {
  result = await pool.query('SELECT * FROM super_admins WHERE username = $1 AND is_active = TRUE', [username]);
} catch(e) {
  try { result = await pool.query('SELECT * FROM super_admins WHERE username = $1', [username]); }
  catch(e2) { return res.status(500).json({ success: false, error: 'Database initializing — please retry in 30 seconds' }); }
}
if (result.rows.length === 0) return res.status(401).json({ success: false, error: 'Invalid' });
const valid = await bcrypt.compare(password, result.rows[0].password_hash);
if (!valid) return res.status(401).json({ success: false, error: 'Invalid' });
// Reuse existing token if present — never regenerate unless logout is called.
// This keeps localStorage valid across server restarts and multiple devices.
let sessionToken = result.rows[0].session_token;
if (!sessionToken) {
  sessionToken = crypto.randomBytes(32).toString('hex');
  await pool.query('UPDATE super_admins SET session_token = $1, last_login = NOW() WHERE id = $2', [sessionToken, result.rows[0].id]);
} else {
  await pool.query('UPDATE super_admins SET last_login = NOW() WHERE id = $1', [result.rows[0].id]);
}
res.json({ success: true, admin_id: sessionToken });
} catch (e) { res.status(500).json({ success: false, error: 'Server error' }); }
});
