      // ── Claude API proxy — users provide their own API key ─────────────────────
app.post('/api/claude-proxy', async (req, res) => {
  const apiKey = req.headers['x-anthropic-key'];
  const userId = req.headers['x-user-id'] || 'anonymous';

  if (!apiKey || apiKey.length < 20) {
    return res.status(401).json({ 
      error: 'ANTHROPIC_API_KEY required', 
      detail: 'Send your API key in the x-anthropic-key header' 
    });
  }

  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 90000);

    // ✅ Clean URL - NO trailing spaces
    const upstream = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
      },
      body: JSON.stringify(req.body),
      signal: controller.signal,
    });

    clearTimeout(timeout);

    const rawText = await upstream.text();
    let data;
    try { data = JSON.parse(rawText); } 
    catch { data = { raw: rawText.slice(0, 500) }; }

    console.log(`[claude-proxy] ${userId} → ${upstream.status} (${rawText.length} bytes)`);

    // Detect rate limit / overload errors and add clear message
    if (upstream.status === 529 || upstream.status === 503) {
      return res.status(upstream.status).json({ 
        error: { message: 'Anthropic API rate limit or overload — wait a few minutes and try again', type: 'rate_limit' },
        ...data 
      });
    }

    res.status(upstream.status).json(data);
  } catch (err) {
    console.error('[claude-proxy] Error:', err.message);
    if (err.name === 'AbortError') {
      return res.status(504).json({ error: 'Gateway timeout', detail: 'Anthropic API took too long' });
    }
    res.status(502).json({ error: 'Proxy request failed', detail: err.message });
  }
});

// ============================================
// GEMINI PROXY — Lead Crawler
// Gebruikt GEMINI_KEY_LEADCRAWLER uit Railway env
// HTML stuurt geen key — server regelt het
// Retry on 503 (Gemini overload) — max 3 attempts with backoff
// ============================================
app.post('/api/gemini-proxy', async (req, res) => {
  const apiKey = process.env.GEMINI_KEY_LEADCRAWLER;
  const userId = req.headers['x-user-id'] || 'anonymous';
  const model  = req.query.model || GEMINI_MODEL || 'gemini-2.5-flash';

  if (!apiKey) {
    return res.status(500).json({
      error: 'GEMINI_KEY_LEADCRAWLER not set',
      detail: 'Voeg GEMINI_KEY_LEADCRAWLER toe in Railway Variables'
    });
  }

  // Server-side rate limiter: max 10 req/min to stay under Gemini free tier (15 RPM)
  const now = Date.now();
  if (!global._geminiReqLog) global._geminiReqLog = [];
  global._geminiReqLog = global._geminiReqLog.filter(t => now - t < 60000);
  if (global._geminiReqLog.length >= 10) {
    const waitMs = 60000 - (now - global._geminiReqLog[0]) + 500;
    console.log(`[gemini-proxy] Rate limit pause ${Math.ceil(waitMs/1000)}s (${global._geminiReqLog.length} req in last 60s)`);
    await new Promise(r => setTimeout(r, waitMs));
    global._geminiReqLog = global._geminiReqLog.filter(t => Date.now() - t < 60000);
  }
  global._geminiReqLog.push(Date.now());

  const MAX_RETRIES = 3;
  let lastData, lastStatus;

  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 90000);

      const upstream = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ...req.body, tools: req.body.tools || [{ google_search: {} }] }),
          signal: controller.signal,
        }
      );

      clearTimeout(timeout);
      const rawText = await upstream.text();
      let data;
      try { data = JSON.parse(rawText); }
      catch { data = { raw: rawText.slice(0, 500) }; }

      lastData = data;
      lastStatus = upstream.status;

      console.log(`[gemini-proxy] ${userId} → ${model} → ${upstream.status} (attempt ${attempt})`);

      // Success
      if (upstream.ok) {
        return res.status(200).json(data);
      }

      // 503 overload — retry with backoff
      if (upstream.status === 503 && attempt < MAX_RETRIES) {
        const wait = attempt * 3000; // 3s, 6s
        console.warn(`[gemini-proxy] 503 overload — retrying in ${wait}ms (attempt ${attempt}/${MAX_RETRIES})`);
        await new Promise(r => setTimeout(r, wait));
        continue;
      }

      // 429 rate limit
      if (upstream.status === 429) {
        return res.status(429).json({
          error: { message: 'Gemini rate limit — even wachten', type: 'rate_limit' },
          ...data
        });
      }

      // 503 overload on final attempt — try Claude as fallback
      if (upstream.status === 503 && attempt >= MAX_RETRIES) {
        const anthropicKey = process.env.ANTHROPIC_API_KEY;
        if (anthropicKey) {
          try {
            console.log('[gemini-proxy] Gemini 503 — falling back to Claude');
            const userText = req.body?.contents?.[0]?.parts?.[0]?.text || '';
            const claudeResp = await fetch('https://api.anthropic.com/v1/messages', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'x-api-key': anthropicKey,
                'anthropic-version': '2023-06-01'
              },
              body: JSON.stringify({
                model: 'claude-haiku-4-5-20251001',
                max_tokens: 1024,
                messages: [{ role: 'user', content: userText }]
              })
            });
            const claudeData = await claudeResp.json();
            const claudeText = claudeData.content?.[0]?.text || '';
            // Return in Gemini-compatible format so client code works unchanged
            return res.json({
              candidates: [{ content: { parts: [{ text: claudeText }] } }],
              _fallback: 'claude'
            });
          } catch(claudeErr) {
            console.error('[gemini-proxy] Claude fallback also failed:', claudeErr.message);
          }
        }
      }
      // Other error — return immediately
      return res.status(upstream.status).json(data);

    } catch (err) {
      if (err.name === 'AbortError') return res.status(504).json({ error: 'Gateway timeout' });
      if (attempt < MAX_RETRIES) {
        await new Promise(r => setTimeout(r, attempt * 2000));
        continue;
      }
      console.error('[gemini-proxy] Error:', err.message);
      return res.status(502).json({ error: 'Proxy request failed', detail: err.message });
    }
  }

  // All retries exhausted
  console.error('[gemini-proxy] All retries failed');
  res.status(503).json({ error: 'Gemini unavailable after retries — try again shortly', ...lastData });
});

