// PATCH /api/admin/access-codes/:id — update code
app.patch('/api/admin/access-codes/:id', verifyAdmin, async (req, res) => {
  const { is_active, ai_calls_limit, ai_calls_used } = req.body;
  try {
    const fields = [];
    const vals = [];
    let i = 1;
    if (is_active !== undefined) { fields.push(`is_active=$${i++}`); vals.push(is_active); }
    if (ai_calls_limit !== undefined) { fields.push(`ai_calls_limit=$${i++}`); vals.push(ai_calls_limit); }
    if (ai_calls_used !== undefined) { fields.push(`ai_calls_used=$${i++}`); vals.push(ai_calls_used); }
    if (!fields.length) return res.status(400).json({ success: false, error: 'Niets om bij te werken' });
    vals.push(req.params.id);
    const r = await pool.query(`UPDATE access_codes SET ${fields.join(',')} WHERE id=$${i} RETURNING *`, vals);
    res.json({ success: true, code: r.rows[0] });
  } catch (e) { res.status(500).json({ success: false, error: e.message }); }
});

