// ── GSC CSV Upload ── (moved here because verifyEngineAccess must be defined first)

app.post('/api/gsc/upload-csv', verifyEngineAccess, upload.single('file'), async (req, res) => {
  try {
    const { profile_id, type } = req.body;
    if (!req.file) return res.status(400).json({ success: false, error: 'No file uploaded' });
    if (!profile_id) return res.status(400).json({ success: false, error: 'profile_id required' });
    if (!type || !['pages', 'queries'].includes(type)) {
      return res.status(400).json({ success: false, error: 'type must be pages or queries' });
    }

    const csvText = req.file.buffer.toString('utf8');
    const lines = csvText.split(/\r?\n/).filter(l => l.trim());
    if (lines.length < 2) {
      return res.status(400).json({ success: false, error: 'CSV empty or invalid' });
    }

    const headers = lines[0].split(',').map(h => h.trim().replace(/^"|"$/g, '').toLowerCase());
    const getIdx = (name) => headers.findIndex(h => h.includes(name.toLowerCase()));

    const urlIdx = getIdx('url') !== -1 ? getIdx('url') : getIdx('page');
    const clickIdx = getIdx('clicks');
    const impIdx = getIdx('impressions');
    const ctrIdx = getIdx('ctr');
    const posIdx = getIdx('position');
    const queryIdx = getIdx('query');
    const keywordIdx = getIdx('keyword') !== -1 ? getIdx('keyword') : queryIdx;

    const rows = [];
    for (let i = 1; i < lines.length; i++) {
      const cols = lines[i].split(',').map(c => c.trim().replace(/^"|"$/g, ''));
      if (cols.length < 2) continue;

      if (type === 'pages') {
        const url = cols[urlIdx] || '';
        if (!url || !url.startsWith('http')) continue;
        rows.push({
          profile_id: parseInt(profile_id),
          url: url,
          clicks: parseInt(cols[clickIdx]) || 0,
          impressions: parseInt(cols[impIdx]) || 0,
          ctr: parseFloat(cols[ctrIdx]) || 0,
          position: parseFloat(cols[posIdx]) || 0,
          uploaded_at: new Date().toISOString()
        });
      } else {
        const query = cols[queryIdx] || cols[keywordIdx] || '';
        if (!query) continue;
        rows.push({
          profile_id: parseInt(profile_id),
          query: query,
          clicks: parseInt(cols[clickIdx]) || 0,
          impressions: parseInt(cols[impIdx]) || 0,
          ctr: parseFloat(cols[ctrIdx]) || 0,
          position: parseFloat(cols[posIdx]) || 0,
          url: cols[urlIdx] || null,
          uploaded_at: new Date().toISOString()
        });
      }
    }

    // Bulk insert
    let inserted = 0;
    const table = type === 'pages' ? 'gsc_pages' : 'gsc_queries';
    const uniqueCol = type === 'pages' ? 'url' : 'query';

    for (const row of rows) {
      try {
        if (type === 'pages') {
          await pool.query(
            `INSERT INTO gsc_pages (profile_id, url, clicks, impressions, ctr, position, uploaded_at)
             VALUES ($1, $2, $3, $4, $5, $6, $7)
             ON CONFLICT (profile_id, url) DO UPDATE SET
             clicks = EXCLUDED.clicks, impressions = EXCLUDED.impressions,
             ctr = EXCLUDED.ctr, position = EXCLUDED.position, uploaded_at = EXCLUDED.uploaded_at`,
            [row.profile_id, row.url, row.clicks, row.impressions, row.ctr, row.position, row.uploaded_at]
          );
        } else {
          await pool.query(
            `INSERT INTO gsc_queries (profile_id, query, clicks, impressions, ctr, position, url, uploaded_at)
             VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
             ON CONFLICT (profile_id, query, url) DO UPDATE SET
             clicks = EXCLUDED.clicks, impressions = EXCLUDED.impressions,
             ctr = EXCLUDED.ctr, position = EXCLUDED.position, uploaded_at = EXCLUDED.uploaded_at`,
            [row.profile_id, row.query, row.clicks, row.impressions, row.ctr, row.position, row.url, row.uploaded_at]
          );
        }
        inserted++;
      } catch (e) {
        console.warn(`[gsc-csv] insert skip: ${e.message}`);
      }
    }

    res.json({ success: true, inserted, total: rows.length, type, preview_ready: type === 'pages' && rows.length > 0 });
  } catch (error) {
    console.error('❌ GSC CSV upload error:', error.message);
    res.status(500).json({ success: false, error: error.message });
  }
});

// ── GSC PREVIEW: show uploaded URLs not yet in tracker_pages ────────────────
app.get('/api/gsc/preview', verifyEngineAccess, async (req, res) => {
  try {
    const profileId = req.query.profile_id;
    if (!profileId) return res.status(400).json({ success: false, error: 'profile_id required' });
    const eu = req.engineUser;
    const codeId = (eu && !eu.isAdmin) ? eu.codeId : null;

    // Return ALL GSC pages for this profile, with an in_tracker flag.
    // This lets the user see AND re-import (sync profile_id) existing URLs.
    const gscR = await pool.query(
      `SELECT g.url, g.clicks, g.impressions, g.ctr, g.position, g.uploaded_at,
         EXISTS (
           SELECT 1 FROM tracker_pages t
           WHERE (t.engine_code_id = $2 OR (t.engine_code_id IS NULL AND $2 IS NULL))
             AND t.url = g.url
         ) as in_tracker
       FROM gsc_pages g
       WHERE g.profile_id = $1
       ORDER BY g.clicks DESC, g.impressions DESC
       LIMIT 200`,
      [profileId, codeId]
    );

    const newCount = gscR.rows.filter(r => !r.in_tracker).length;
    const existingCount = gscR.rows.filter(r => r.in_tracker).length;

    res.json({
      success: true,
      urls: gscR.rows,
      new_count: newCount,
      existing_count: existingCount,
      total_available: gscR.rows.length
    });
  } catch(e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

// ── GSC CONFIRM IMPORT: import selected URLs into tracker_pages ─────────────
// If a URL already exists for this engine, UPDATE its profile_id and GSC data
// instead of silently skipping. This fixes the "0 pages after GSC import" bug
// where URLs existed under a different profile_id.
app.post('/api/gsc/confirm-import', verifyEngineAccess, async (req, res) => {
  try {
    const { profile_id, urls, batch_label } = req.body;
    if (!profile_id) return res.status(400).json({ success: false, error: 'profile_id required' });
    if (!Array.isArray(urls) || !urls.length) return res.status(400).json({ success: false, error: 'urls array required' });
    const eu = req.engineUser;
    const codeId = (eu && !eu.isAdmin) ? eu.codeId : null;
    const batchId = batch_label || ('gsc_' + Date.now());
    let imported = 0;
    let updated = 0;
    let skipped = 0;
    const results = [];
    for (const url of urls) {
      try {
        // Get GSC data for this URL
        const gscR = await pool.query(
          'SELECT clicks, impressions, ctr, position FROM gsc_pages WHERE profile_id = $1 AND url = $2',
          [profile_id, url]
        );
        const gsc = gscR.rows[0] || {};
        const urlObj = new URL(url);
        const slug = urlObj.pathname.split('/').filter(Boolean).pop() || '/';

        // Step 1: Try INSERT. If URL already exists for this engine, catch the conflict
        // and UPDATE the existing row with new profile_id + GSC data instead of skipping.
        let r, isUpdate = false;
        try {
          r = await pool.query(
            `INSERT INTO tracker_pages (engine_code_id, profile_id, url, slug, keyword, check_frequency, next_check_at, gsc_impressions, gsc_clicks, gsc_position, gsc_ctr, import_batch, is_active)
             VALUES ($1,$2,$3,$4,$5,$6,NOW(),$7,$8,$9,$10,$11,TRUE)
             RETURNING id`,
            [codeId, profile_id, url, slug, null, '3days',
             parseInt(gsc.impressions) || null,
             parseInt(gsc.clicks) || null,
             parseFloat(gsc.position) || null,
             parseFloat(gsc.ctr) || null,
             batchId]
          );
        } catch(insertErr) {
          // Unique constraint violation — URL already exists for this engine.
          // Update the existing row with new profile_id and GSC data.
          if (insertErr.code === '23505' || /unique|duplicate/i.test(insertErr.message)) {
            isUpdate = true;
            r = await pool.query(
              `UPDATE tracker_pages SET
                 profile_id = $1,
                 gsc_impressions = $2,
                 gsc_clicks = $3,
                 gsc_position = $4,
                 gsc_ctr = $5,
                 import_batch = $6,
                 slug = $7,
                 updated_at = NOW()
               WHERE (engine_code_id = $8 OR ($8 IS NULL AND engine_code_id IS NULL))
                 AND url = $9
               RETURNING id`,
              [profile_id,
               parseInt(gsc.impressions) || null,
               parseInt(gsc.clicks) || null,
               parseFloat(gsc.position) || null,
               parseFloat(gsc.ctr) || null,
               batchId,
               slug,
               codeId,
               url]
            );
          } else {
            throw insertErr;
          }
        }

        if (r.rows.length) {
          if (isUpdate) {
            updated++;
            results.push({ url, id: r.rows[0].id, status: 'updated' });
          } else {
            imported++;
            results.push({ url, id: r.rows[0].id, status: 'imported' });
          }
        } else {
          skipped++;
          results.push({ url, status: 'already_exists' });
        }
      } catch(e) {
        skipped++;
        results.push({ url, status: 'error', error: e.message });
      }
    }
    // After the import loop: batch-update profile_id for ALL existing tracker_pages
    // that match GSC URLs for this profile. This catches URLs that weren't in the
    // user's import selection but still need their profile_id synced.
    let synced = 0;
    try {
      const syncR = await pool.query(
        `UPDATE tracker_pages t
         SET profile_id = $1,
             gsc_impressions = COALESCE(t.gsc_impressions, gsc.impressions::int),
             gsc_clicks = COALESCE(t.gsc_clicks, gsc.clicks::int),
             gsc_position = COALESCE(t.gsc_position, gsc.position::numeric),
             gsc_ctr = COALESCE(t.gsc_ctr, gsc.ctr::numeric),
             updated_at = NOW()
         FROM (
           SELECT url, clicks, impressions, position, ctr
           FROM gsc_pages WHERE profile_id = $1
         ) gsc
         WHERE (t.engine_code_id = $2 OR ($2 IS NULL AND t.engine_code_id IS NULL))
           AND t.url = gsc.url
           AND (t.profile_id IS DISTINCT FROM $1)
         RETURNING t.id`,
        [profile_id, codeId]
      );
      synced = syncR.rows.length;
    } catch(syncErr) {
      console.warn('[gsc-confirm-import] profile sync warning:', syncErr.message);
    }

    res.json({ success: true, imported, updated, skipped, synced, batch_id: batchId, results });
  } catch(e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

// ── COMPETITOR ANALYSIS via SerpAPI ─────────────────────────────────────────
// Fetches live top 5 Google results + People Also Ask for competitive gap analysis
// Key diagnostic — shows which SerpAPI key source is active (does NOT expose the key)
app.get('/api/serp/key-status', verifyEngineAccess, async (req, res) => {
  const serpKey = resolveSerpapiKey(req);
  const geminiKey = resolveGeminiKey(req);
  const hasCodeKey = !!(req.engineUser && req.engineUser.code && req.engineUser.code.serpapi_key);
  const hasEnvKey = !!process.env.SERPAPI_KEY;
  const hasHeaderKey = !!req.headers['x-serpapi-key'];

  // Test the key with a simple search
  let serpTest = 'not_tested';
  if (serpKey) {
    try {
      const testR = await fetch('https://serpapi.com/search?engine=google&q=test&num=1&api_key=' + encodeURIComponent(serpKey), { signal: AbortSignal.timeout(5000) });
      const testD = await testR.json();
      serpTest = testD.error ? ('invalid: ' + (typeof testD.error === 'string' ? testD.error : JSON.stringify(testD.error).substring(0, 100))) : 'valid';
    } catch(e) { serpTest = 'error: ' + e.message; }
  }

  res.json({
    success: true,
    serpapi: {
      configured: !!serpKey,
      source: hasHeaderKey ? 'header' : (hasCodeKey ? 'per-code' : (hasEnvKey ? 'platform-env' : 'none')),
      key_prefix: serpKey ? serpKey.substring(0, 4) + '...' + serpKey.substring(serpKey.length - 4) : null,
      test_result: serpTest,
      code_id: req.engineUser ? req.engineUser.codeId : null
    },
    gemini: {
      configured: !!geminiKey,
      source: req.headers['x-gemini-key'] ? 'header' : (process.env.GEMINI_API_KEY ? 'env' : 'none')
    }
  });
});

app.get('/api/serp/competitors', verifyEngineAccess, async (req, res) => {
  const keyword = req.query.keyword;
  if (!keyword) return res.status(400).json({ success: false, error: 'keyword required' });
  const serpKey = resolveSerpapiKey(req);
  if (!serpKey) return res.status(503).json({ success: false, error: 'SerpAPI key not configured' });

  try {
    const params = new URLSearchParams({
      engine: 'google', q: keyword, api_key: serpKey,
      num: '5', hl: 'en', gl: 'us'
    });
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 10000);
    const r = await fetch(`https://serpapi.com/search?${params}`, { signal: ctrl.signal });
    clearTimeout(t);
    const data = await r.json();

    // Extract top 5 organic results
    const top5 = (data.organic_results || []).slice(0, 5).map(function(o) {
      return { position: o.position, title: o.title || '', snippet: o.snippet || '', url: o.link || '', displayed_url: o.displayed_link || '' };
    });

    // Extract People Also Ask
    const ppa = (data.related_questions || []).map(function(q) {
      return { question: q.question || '', snippet: q.snippet || '' };
    }).slice(0, 8);

    // Extract AI Overview (if present)
    var aiOverview = null;
    if (data.answer_box) {
      aiOverview = {
        type: data.answer_box.type || 'overview',
        title: data.answer_box.title || '',
        answer: data.answer_box.answer || data.answer_box.snippet || ''
      };
    }

    // Extract related searches
    const related = (data.related_searches || []).map(function(s) {
      return s.query || '';
    }).filter(Boolean).slice(0, 10);

    res.json({
      success: true,
      keyword: keyword,
      top5: top5,
      people_also_ask: ppa,
      ai_overview: aiOverview,
      related_searches: related,
      total_results: data.search_information?.total_results || 'unknown'
    });
    // Cache the result
    _cacheSet('serp:' + keyword.toLowerCase().trim() + ':' + glParam + ':' + locationStr, {
      success: true, keyword, top5, people_also_ask: ppa, ai_overview: aiOverview, related_searches: related,
      total_results: data.search_information?.total_results || 'unknown'
    }, CACHE_TTL.serper);
  } catch(e) {
    console.error('[serp competitors]', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

// ── CONTENT INTELLIGENCE — Deep competitor analysis + content gaps ────────────
// Analyzes top 10 competitors for a keyword, extracts content patterns,
// identifies gaps vs your page, and generates a "beat them" brief.
app.get('/api/serp/intelligence', verifyEngineAccess, async (req, res) => {
  const keyword = req.query.keyword;
  const yourUrl = req.query.url || '';
  if (!keyword) return res.status(400).json({ success: false, error: 'keyword required' });
  const serpKey = resolveSerpapiKey(req);
  const geminiKey = resolveGeminiKey(req);
  if (!serpKey) return res.status(503).json({ success: false, error: 'SerpAPI key not configured' });

  // Geo: comes from profile geo_focus only — no hardcoding, no keyword sniffing
  const locationStr = req.query.location || req.query.geo || '';
  const glParam = req.query.gl || 'us';

  try {
    // Check cache first — SERP results valid for 6 hours
    const cacheKey = 'serp:' + keyword.toLowerCase().trim() + ':' + glParam + ':' + locationStr;
    const cached = _cacheGet(cacheKey);
    if (cached) {
      console.log('[serp-intelligence] Cache hit for:', keyword);
      return res.json({ ...cached, _cached: true });
    }

    // 1. Fetch top 10 Google results
    const serpParams = { engine: 'google', q: keyword, api_key: serpKey, num: '10', hl: 'en', gl: glParam };
    if (locationStr) serpParams.location = locationStr;
    const params = new URLSearchParams(serpParams);
    let serpData;
    let usedFallback = false;
    try {
      const ctrl = new AbortController();
      const t = setTimeout(() => ctrl.abort(), 12000);
      const r = await fetch(`https://serpapi.com/search?${params}`, { signal: ctrl.signal });
      clearTimeout(t);
      serpData = await r.json();
    } catch(e) {
      console.warn('[serp intelligence] SerpAPI fetch failed:', e.message, '— trying Serper fallback');
      serpData = { error: e.message };
    }

    // If SerpAPI fails (auth error, timeout), try Serper.dev fallback
    if (serpData.error || !serpData.organic_results) {
      console.warn('[serp intelligence] SerpAPI error/fallback, trying Serper:', typeof serpData.error === 'string' ? serpData.error : 'no results');
      try {
        const serperCtrl = new AbortController();
        const serperT = setTimeout(() => serperCtrl.abort(), 10000);
        const serperR = await fetch('https://google.serper.dev/search', {
          method: 'POST',
          headers: { 'X-API-KEY': serpKey, 'Content-Type': 'application/json' },
          body: JSON.stringify({ q: keyword, num: 10, hl: 'en', gl: glParam, ...(locationStr ? { location: locationStr } : {}) }),
          signal: serperCtrl.signal
        });
        clearTimeout(serperT);
        const serperData = await serperR.json();
        if (serperData && serperData.organic) {
          // Normalize Serper format to match SerpAPI
          serpData = {
            organic_results: serperData.organic.map((r, i) => ({ position: i + 1, title: r.title, link: r.link, snippet: r.snippet })),
            related_questions: (serperData.peopleAlsoAsk || []).map(q => ({ question: q.question, snippet: q.snippet })),
            related_searches: (serperData.relatedSearches || []).map(s => s.query || s).filter(Boolean),
            answer_box: serperData.answerBox ? { type: 'overview', answer: serperData.answerBox.answer || serperData.answerBox.snippet || '' } : null
          };
          usedFallback = true;
          console.log('[serp intelligence] Serper fallback successful,', serpData.organic_results.length, 'results');
        }
      } catch(serperErr) {
        console.error('[serp intelligence] Serper fallback also failed:', serperErr.message);
        return res.status(503).json({ success: false, error: 'SerpAPI: ' + (typeof serpData.error === 'string' ? serpData.error : 'Both SerpAPI and Serper failed. Check your API key.') + (usedFallback ? '' : ' Your key may be expired or for a different service.') });
      }
    }

    const organic = (serpData.organic_results || []).slice(0, 10);
    if (!organic.length) {
      return res.json({ success: true, keyword, your_url: yourUrl, competitors: [], people_also_ask: [], related_searches: [], ai_overview: null, intelligence_brief: null, notice: 'No organic results found for this keyword. Try a broader or more specific search term.' });
    }

    const paa = (serpData.related_questions || []).slice(0, 8).map(q => ({ question: q.question || '', snippet: q.snippet || '' }));
    const related = (serpData.related_searches || []).slice(0, 10).map(s => s.query || '').filter(Boolean);
    const aiOverview = serpData.answer_box ? {
      type: serpData.answer_box.type || 'overview',
      answer: serpData.answer_box.answer || serpData.answer_box.snippet || ''
    } : null;

    // 2. Analyze each competitor page (with fallback to basic SERP data)
    const competitorAnalysis = [];
    for (const result of organic) {
      const compUrl = result.link || '';
      if (!compUrl || compUrl === yourUrl) continue;
      try {
        const compData = await quickPageAnalyze(compUrl);
        competitorAnalysis.push({
          position: result.position,
          url: compUrl,
          title: result.title || '',
          snippet: result.snippet || '',
          word_count: compData.wordCount,
          heading_count: compData.headingCount,
          h1: compData.h1,
          h2s: compData.h2s,
          has_schema: compData.hasSchema,
          schema_types: compData.schemaTypes,
          has_faq: compData.hasFAQ,
          has_author: compData.hasAuthor,
          internal_links: compData.internalLinks,
          external_links: compData.externalLinks,
          images: compData.images,
          images_with_alt: compData.imagesWithAlt,
          meta_title_length: compData.metaTitleLength,
          meta_desc_length: compData.metaDescLength,
          avg_paragraph_length: compData.avgParagraphLength
        });
      } catch(e) {
        // FALLBACK: still include competitor with basic SERP data even if deep analysis fails
        competitorAnalysis.push({
          position: result.position,
          url: compUrl,
          title: result.title || '',
          snippet: result.snippet || '',
          word_count: null, heading_count: null,
          h1: '', h2s: [],
          has_schema: false, schema_types: [],
          has_faq: false, has_author: false,
          internal_links: 0, external_links: 0,
          images: 0, images_with_alt: 0,
          meta_title_length: 0, meta_desc_length: 0,
          avg_paragraph_length: 0,
          _fetch_error: e.message
        });
      }
    }

    // If NO competitors were successfully analyzed at all, still return basic SERP data
    if (!competitorAnalysis.length) {
      return res.json({ success: true, keyword, your_url: yourUrl, competitors: [], people_also_ask: paa, related_searches: related, ai_overview: aiOverview, intelligence_brief: null, notice: 'Competitor pages could not be fetched for analysis, but SERP data is available.' });
    }

    // 3. Analyze your page (if URL provided)
    let yourAnalysis = null;
    if (yourUrl) {
      try {
        yourAnalysis = await quickPageAnalyze(yourUrl);
      } catch(e) {
        yourAnalysis = { error: e.message };
      }
    }

    // 4. Generate intelligence brief via Gemini
    let brief = null;
    if (geminiKey && competitorAnalysis.length) {
      // Slim competitor payload to avoid token overflow truncation
      const slimCompetitors = competitorAnalysis.map(c => ({
        position: c.position,
        url: c.url,
        title: c.title,
        snippet: c.snippet,
        word_count: c.word_count,
        h1: c.h1,
        h2s: (c.h2s || []).slice(0, 6),
        has_schema: c.has_schema,
        schema_types: c.schema_types,
        has_faq: c.has_faq,
        has_author: c.has_author,
        avg_paragraph_length: c.avg_paragraph_length
      }));

      const prompt = `You are an elite SEO content strategist. Analyze this competitor data and generate a "beat them" content brief.

KEYWORD: "${keyword}"
${yourUrl ? 'YOUR PAGE: ' + yourUrl : ''}
${yourAnalysis && !yourAnalysis.error ? 'YOUR STATS: ' + JSON.stringify(yourAnalysis) : ''}

COMPETITORS (${slimCompetitors.length} analyzed):
${JSON.stringify(slimCompetitors, null, 2)}

PEOPLE ALSO ASK:
${paa.map(q => '- ' + q.question).join('\n')}

RELATED SEARCHES: ${related.join(', ')}

Generate a JSON response with this exact structure:
{
  "content_gaps": ["topic competitors cover that you don't", "another gap"],
  "competitor_patterns": {"avg_word_count": 2500, "common_h2s": ["h2 1", "h2 2"], "schema_types_used": ["FAQPage", "Article"]},
  "beat_them_brief": {
    "target_word_count": 2800,
    "recommended_h2s": ["Better H2 One", "Better H2 Two", "Better H2 Three"],
    "topics_to_cover": ["topic 1", "topic 2"],
    "schema_to_add": ["FAQPage", "HowTo"],
    "statistics_to_include": ["Find 2-3 real statistics about this topic"],
    "paa_to_answer": ["answer these people also ask questions directly"],
    "meta_title_suggestion": "SEO Title with Number and Year: Benefit",
    "meta_description_suggestion": "Compelling 155-char description with CTA",
    "voice_search_optimization": "30-50 word natural language answer for voice"
  },
  "priority_actions": [
    {"action": "specific action", "impact": "high/medium/low", "effort": "1-10"}
  ]
}`;

      try {
        const gemResult = await callGeminiWithFallback(geminiKey, {
          contents: [{ parts: [{ text: prompt }] }],
          generationConfig: { temperature: 0.3, maxOutputTokens: 8192, responseMimeType: 'application/json' }
        });
        if (gemResult.ok) {
          const rawText = gemResult.data?.candidates?.[0]?.content?.parts?.[0]?.text || '';
          brief = extractJsonFromText(rawText);
          if (!brief) {
            console.warn('[extractJsonFromText] null result — Pipeline brief truncated; returning partial data without brief.');
            // Don't 502 — competitor data + PAA + related searches were successfully fetched,
            // return them so the UI can still render the competitor table
          }
        }
      } catch(e) { console.warn('[intelligence] Gemini brief failed:', e.message); }
    }

    res.json({
      success: true,
      keyword: keyword,
      your_url: yourUrl,
      your_analysis: yourAnalysis,
      competitors: competitorAnalysis,
      people_also_ask: paa,
      related_searches: related,
      ai_overview: aiOverview,
      intelligence_brief: brief
    });

  } catch(e) {
    console.error('[serp intelligence]', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

// Quick page analysis — fetches a URL and extracts content stats
async function quickPageAnalyze(url) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 8000);
  try {
    const response = await fetch(url, {
      signal: controller.signal,
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' }
    });
    clearTimeout(timeout);
    const html = await response.text();
    return analyzeHtmlStats(html, url);
  } catch(e) {
    clearTimeout(timeout);
    throw e;
  }
}

// Extract content stats from HTML string
function analyzeHtmlStats(html, url) {
  const text = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '').replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
  const cleanText = text.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const words = cleanText.split(/\s+/).filter(w => w.length > 0);
  const wordCount = words.length;

  const h1s = [...text.matchAll(/<h1[^>]*>([\s\S]*?)<\/h1>/gi)].map(m => m[1].replace(/<[^>]+>/g, '').trim()).filter(Boolean);
  const h2s = [...text.matchAll(/<h2[^>]*>([\s\S]*?)<\/h2>/gi)].map(m => m[1].replace(/<[^>]+>/g, '').trim()).filter(Boolean);
  const h3s = [...text.matchAll(/<h3[^>]*>([\s\S]*?)<\/h3>/gi)].map(m => m[1].replace(/<[^>]+>/g, '').trim()).filter(Boolean);

  const schemaScripts = [...html.matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)].map(m => m[1]);
  const schemaTypes = [];
  schemaScripts.forEach(s => {
    try {
      const data = JSON.parse(s);
      const extractTypes = (obj) => {
        if (Array.isArray(obj)) obj.forEach(extractTypes);
        else if (obj && obj['@type']) {
          const types = Array.isArray(obj['@type']) ? obj['@type'] : [obj['@type']];
          types.forEach(t => { if (!schemaTypes.includes(t)) schemaTypes.push(t); });
        }
        if (obj && obj['@graph']) extractTypes(obj['@graph']);
      };
      extractTypes(data);
    } catch(e) {}
  });

  const hasFAQ = /<[^>]*class=["'][^"']*faq[^"']*["']|<[^>]*id=["'][^"']*faq[^"']*["']/i.test(html) ||
    /frequently asked|common questions/i.test(cleanText);
  const hasAuthor = /<[^>]*class=["'][^"']*author[^"']*["']|<[^>]*rel=["']author["']/i.test(html) ||
    /about the author|written by/i.test(html);

  const links = [...html.matchAll(/<a[^>]+href=["']([^"']+)["']/gi)].map(m => m[1]);
  let baseDomain = '';
  try { baseDomain = new URL(url).hostname.replace('www.', ''); } catch(e) {}
  const internalLinks = links.filter(l => {
    try { return new URL(l, url).hostname.replace('www.', '') === baseDomain; } catch(e) { return false; }
  }).length;
  const externalLinks = links.filter(l => {
    try { return new URL(l, url).hostname.replace('www.', '') !== baseDomain && !l.startsWith('#') && !l.startsWith('mailto:'); } catch(e) { return false; }
  }).length;

  const images = [...html.matchAll(/<img[^>]*>/gi)].length;
  const imagesWithAlt = [...html.matchAll(/<img[^>]*alt=["'][^"']+["'][^>]*>/gi)].length;

  const metaTitle = (html.match(/<title>([\s\S]*?)<\/title>/i) || ['', ''])[1].trim();
  const metaDesc = (html.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["']/i) || html.match(/<meta[^>]*content=["']([^"']+)["'][^>]*name=["']description["']/i) || ['', ''])[1].trim();

  const paragraphs = cleanText.split(/\n+/).filter(p => p.trim().length > 20);
  const avgParagraphLength = paragraphs.length ? Math.round(paragraphs.reduce((s, p) => s + p.split(/\s+/).length, 0) / paragraphs.length) : 0;

  return {
    wordCount, headingCount: h1s.length + h2s.length + h3s.length,
    h1: h1s[0] || '', h2s: h2s.slice(0, 10), h3s: h3s.slice(0, 10),
    hasSchema: schemaTypes.length > 0, schemaTypes,
    hasFAQ, hasAuthor,
    internalLinks, externalLinks, images, imagesWithAlt,
    metaTitleLength: metaTitle.length, metaDescLength: metaDesc.length,
    avgParagraphLength
  };
}

// ── META TITLE + DESCRIPTION RESEARCH — CTR-optimized competitor analysis ─────
// Extracts all competitor meta titles + descriptions from Google SERP,
// analyzes CTR patterns (numbers, power words, length, emotion),
// and generates 5+ alternatives that beat the competition.
app.get('/api/serp/meta-research', verifyEngineAccess, async (req, res) => {
  const keyword = req.query.keyword;
  const currentTitle = req.query.current_title || '';
  const currentDesc = req.query.current_description || '';
  if (!keyword) return res.status(400).json({ success: false, error: 'keyword required' });
  const serpKey = resolveSerpapiKey(req);
  const geminiKey = resolveGeminiKey(req);
  if (!serpKey) return res.status(503).json({ success: false, error: 'SerpAPI key not configured' });

  try {
    // 1. Fetch Google SERP
    const params = new URLSearchParams({
      engine: 'google', q: keyword, api_key: serpKey,
      num: '10', hl: 'en', gl: 'us'
    });
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 10000);
    const r = await fetch(`https://serpapi.com/search?${params}`, { signal: ctrl.signal });
    clearTimeout(t);
    const serpData = await r.json();

    const organic = (serpData.organic_results || []).slice(0, 10);

    // 2. Extract + analyze each competitor's meta title + description
    const competitors = organic.map(function(o) {
      var title = o.title || '';
      var desc = o.snippet || '';
      return {
        position: o.position,
        url: o.link || '',
        title: title,
        description: desc,
        title_length: title.length,
        desc_length: desc.length,
        has_number: /\d/.test(title),
        has_year: /20\d\d/.test(title),
        has_power_word: /\b(best|ultimate|complete|guide|proven|secret|exclusive|free|top|essential|definitive|expert|exclusive|now|today|easy|quick|simple|ultimate)\b/i.test(title),
        has_question: /\?/.test(title),
        has_brackets: /[\[\{\(]/.test(title),
        has_pipe_dash: /\||\s-\s/.test(title),
        emotion_score: _scoreEmotion(title),
        word_count: title.split(/\s+/).length
      };
    });

    // 3. Pattern analysis
    var withNumbers = competitors.filter(function(c) { return c.has_number; }).length;
    var withYear = competitors.filter(function(c) { return c.has_year; }).length;
    var withPowerWord = competitors.filter(function(c) { return c.has_power_word; }).length;
    var withQuestion = competitors.filter(function(c) { return c.has_question; }).length;
    var withBrackets = competitors.filter(function(c) { return c.has_brackets; }).length;
    var avgTitleLen = Math.round(competitors.reduce(function(s,c){return s+c.title_length},0) / competitors.length);
    var avgDescLen = Math.round(competitors.reduce(function(s,c){return s+c.desc_length},0) / competitors.length);

    var patterns = {
      use_numbers: withNumbers >= competitors.length * 0.4,
      use_year: withYear >= competitors.length * 0.3,
      use_power_words: withPowerWord >= competitors.length * 0.5,
      use_questions: withQuestion >= competitors.length * 0.2,
      use_brackets: withBrackets >= competitors.length * 0.2,
      avg_title_length: avgTitleLen,
      avg_description_length: avgDescLen,
      dominant_patterns: []
    };
    if (patterns.use_numbers) patterns.dominant_patterns.push('Numbers in title');
    if (patterns.use_year) patterns.dominant_patterns.push('Year (2025) in title');
    if (patterns.use_power_words) patterns.dominant_patterns.push('Power words (Best, Ultimate, Guide)');
    if (patterns.use_questions) patterns.dominant_patterns.push('Question format');
    if (patterns.use_brackets) patterns.dominant_patterns.push('Brackets/parentheses');

    // 4. Score current meta (if provided)
    var currentScore = null;
    if (currentTitle) {
      currentScore = {
        title_score: _scoreMetaTitle(currentTitle, patterns),
        description_score: _scoreMetaDescription(currentDesc, patterns),
        issues: []
      };
      if (currentTitle.length < 30) currentScore.issues.push('Title too short (< 30 chars)');
      if (currentTitle.length > 60) currentScore.issues.push('Title too long (> 60 chars)');
      if (!/\d/.test(currentTitle)) currentScore.issues.push('No number in title — reduces CTR by ~36%');
      if (!/[A-Z]/.test(currentTitle)) currentScore.issues.push('No capitalization/emphasis');
      if (currentDesc.length < 80) currentScore.issues.push('Description too short (< 80 chars)');
      if (currentDesc.length > 155) currentScore.issues.push('Description too long (> 155 chars)');
      if (!/\b(best|ultimate|complete|guide|proven|learn|discover|find out|see why)\b/i.test(currentDesc)) currentScore.issues.push('No action verb in description');
    }

    // 5. Generate alternatives via Gemini
    var alternatives = null;
    if (geminiKey) {
      var altPrompt = `You are an elite CTR copywriter. Analyze these competitor meta titles and descriptions for "${keyword}", then generate 5+ alternatives that will OUTPERFORM them.

CURRENT COMPETITOR META DATA:
${competitors.slice(0, 7).map(function(c,i) {
  return (i+1) + '. "' + c.title + '"\n   "' + c.description + '"';
}).join('\n')}
${currentTitle ? '\nYOUR CURRENT META:\nTitle: "' + currentTitle + '"\nDesc: "' + currentDesc + '"' : ''}

PATTERNS FOUND:
- ${patterns.dominant_patterns.join('\n- ') || 'None dominant'}
- Avg title length: ${avgTitleLen} chars
- Avg description length: ${avgDescLen} chars

CTR BEST PRACTICES:
- Include specific numbers (increases CTR 36%)
- Use year when relevant (signals freshness)
- Power words: Best, Ultimate, Proven, Complete, Essential, Expert
- Brackets increase CTR: [2025 Guide], (Step-by-Step)
- Front-load the keyword
- Description: action verb + benefit + urgency
- 50-60 chars for title, 140-155 for description

Generate JSON:
{
  "analysis": "2-3 sentence summary of what competitors are doing and the biggest opportunity",
  "alternatives": [
    {
      "title": "Optimized title 50-60 chars with number + power word + year",
      "description": "Optimized description 140-155 chars with action verb + benefit",
      "why_it_works": "Specific explanation of CTR psychology used",
      "predicted_ctr_lift": "high/medium/low"
    }
  ],
  "best_practices_checklist": [
    "✓ Numbers in title (36% CTR boost)",
    "✓ Power words (Best, Ultimate, Guide)",
    "✓ Year signals freshness",
    "✓ Description has action CTA"
  ]
}`;

      try {
        var gemResult = await callGeminiWithFallback(geminiKey, {
          contents: [{ parts: [{ text: altPrompt }] }],
          generationConfig: { temperature: 0.4, maxOutputTokens: 4096, responseMimeType: 'application/json' }
        });
        if (gemResult.ok) {
          var raw = gemResult.data?.candidates?.[0]?.content?.parts?.[0]?.text || '';
          alternatives = extractJsonFromText(raw);
          if (!alternatives) {
            console.warn('[extractJsonFromText] null result — Meta-research: AI returned truncated or invalid JSON — try again.');
            return res.status(502).json({ success: false, error: 'Meta-research: AI returned truncated or invalid JSON — try again.' });
          }
        }
      } catch(e) { console.warn('[meta-research] Gemini failed:', e.message); }
    }

    res.json({
      success: true,
      keyword: keyword,
      competitors_analyzed: competitors.length,
      patterns: patterns,
      competitor_meta: competitors.slice(0, 7),
      current_meta_score: currentScore,
      alternatives: alternatives
    });

  } catch(e) {
    console.error('[meta-research]', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

// Score emotion/persuasion in a meta title
function _scoreEmotion(title) {
  var score = 0;
  if (/\d/.test(title)) score += 2; // numbers
  if (/20\d\d/.test(title)) score += 1; // year
  if (/\b(best|ultimate|top|essential)\b/i.test(title)) score += 3; // superlatives
  if (/\b(proven|secret|exclusive|guaranteed)\b/i.test(title)) score += 2; // trust
  if (/\b(now|today|urgent|limited)\b/i.test(title)) score += 2; // urgency
  if (/\b(how to|why|what)\b/i.test(title)) score += 1; // curiosity
  if (/\?/.test(title)) score += 2; // question
  if (/[\[\{\(]/i.test(title)) score += 2; // brackets
  if (/\b(free|save|easy|quick|simple)\b/i.test(title)) score += 1; // benefit
  return Math.min(score, 15);
}

// Score a meta title against competitor patterns
function _scoreMetaTitle(title, patterns) {
  var score = 50; // base
  var len = title.length;
  if (len >= 45 && len <= 60) score += 15;
  else if (len >= 30 && len < 45) score += 5;
  else if (len > 60) score -= 10;
  else score -= 5;
  if (/\d/.test(title)) score += 10;
  if (/20\d\d/.test(title)) score += 5;
  if (/\b(best|ultimate|complete|guide|proven|top|essential|definitive)\b/i.test(title)) score += 10;
  if (/\?/.test(title)) score += 5;
  if (/[\[\{\(]/i.test(title)) score += 5;
  if (patterns.use_brackets && /[\[\{\(]/i.test(title)) score += 3;
  if (/\b(now|today)\b/i.test(title)) score += 3;
  if (/[A-Z]{2,}/.test(title)) score -= 5; // ALL CAPS penalty
  return Math.min(100, Math.max(0, score));
}

// Score a meta description against competitor patterns
function _scoreMetaDescription(desc, patterns) {
  var score = 50;
  var len = desc.length;
  if (len >= 120 && len <= 155) score += 15;
  else if (len >= 80 && len < 120) score += 5;
  else if (len > 155) score -= 10;
  else score -= 5;
  if (/\b(learn|discover|find out|see why|read|get|download|try|start)\b/i.test(desc)) score += 10; // CTA
  if (/\b(best|ultimate|proven|essential|free)\b/i.test(desc)) score += 5;
  if (/\b(now|today|limited|exclusive)\b/i.test(desc)) score += 5; // urgency
  if (/\d/.test(desc)) score += 5;
  if (/\?/.test(desc)) score += 3;
  if (/\.{3}$/.test(desc)) score += 3; // ellipsis creates curiosity
  return Math.min(100, Math.max(0, score));
}

// Extract JSON from text (handles markdown code blocks, truncated responses, extra text)
function extractJsonFromText(text) {
  if (!text || typeof text !== 'string') return null;

  // Strip markdown fences
  let cleaned = text
    .replace(/```json\s*/gi, '')
    .replace(/```\s*/gi, '')
    .trim();

  // Try direct parse first
  try { return JSON.parse(cleaned); } catch (_) {}

  // Try brace-depth extraction (handles extra text before/after JSON)
  let startIdx = cleaned.indexOf('{');
  if (startIdx === -1) return null;

  let depth = 0, endIdx = -1;
  for (let i = startIdx; i < cleaned.length; i++) {
    if (cleaned[i] === '{') depth++;
    else if (cleaned[i] === '}') {
      depth--;
      if (depth === 0) { endIdx = i; break; }
    }
  }

  if (endIdx === -1) {
    // Truncated response — log warning instead of throwing
    console.warn('[extractJsonFromText] Unclosed JSON object — AI response may have been truncated');
    return null;
  }

  try { return JSON.parse(cleaned.slice(startIdx, endIdx + 1)); } catch (_) {}
  return null;
}

// ── CONTENT PIPELINE: RESEARCH → BRIEF → DRAFT → REVIEW → PUBLISH ───────────
app.post('/api/content/pipeline', verifyEngineAccess, async (req, res) => {
  const { keyword, url, profile_id } = req.body;
  if (!keyword) return res.status(400).json({ success: false, error: 'keyword required' });
  const geminiKey = resolveGeminiKey(req);
  const claudeKey = resolveClaudeKey(req);
  const serpKey = resolveSerpapiKey(req);

  const pipeline = {
    keyword, url,
    stages: { research: null, brief: null, draft: null, review: null, publish: null },
    started_at: new Date().toISOString()
  };

  try {
    // ═══ STAGE 1: RESEARCH ═══════════════════════════════════════════════════
    console.log(`[pipeline] Stage 1/5: RESEARCH — "${keyword}"`);
    const serpParams = new URLSearchParams({ engine: 'google', q: keyword, api_key: serpKey, num: '10', hl: 'en', gl: 'us' });
    const serpCtrl = new AbortController();
    setTimeout(() => serpCtrl.abort(), 12000);
    const serpR = await fetch(`https://serpapi.com/search?${serpParams}`, { signal: serpCtrl.signal });
    const serpData = await serpR.json();

    const organic = (serpData.organic_results || []).slice(0, 10);
    const paa = (serpData.related_questions || []).slice(0, 8).map(q => ({ question: q.question || '', snippet: q.snippet || '' }));
    const related = (serpData.related_searches || []).slice(0, 10).map(s => s.query || '').filter(Boolean);
    const aiOverview = serpData.answer_box ? { type: serpData.answer_box.type || 'overview', answer: serpData.answer_box.answer || serpData.answer_box.snippet || '' } : null;

    // Quick competitor analysis
    const competitorPromises = organic.slice(0, 5).map(async (result) => {
      try {
        const stats = await quickPageAnalyze(result.link);
        return { position: result.position, url: result.link, title: result.title || '', snippet: result.snippet || '', word_count: stats.wordCount, heading_count: stats.headingCount, h2_count: stats.h2s.length, schema_types: stats.schemaTypes, has_faq: stats.hasFAQ };
      } catch(e) { return { position: result.position, url: result.link, title: result.title || '', snippet: result.snippet || '', error: e.message }; }
    });
    const competitors = (await Promise.all(competitorPromises)).filter(c => !c.error);
    const avgWords = competitors.length ? Math.round(competitors.reduce((s, c) => s + (c.word_count || 0), 0) / competitors.length) : 0;

    pipeline.stages.research = {
      status: 'complete',
      keyword, url,
      top5: organic.slice(0, 5).map(o => ({ position: o.position, title: o.title, url: o.link, snippet: o.snippet })),
      people_also_ask: paa,
      related_searches: related,
      ai_overview: aiOverview,
      competitors: competitors.slice(0, 5),
      competitor_avg_words: avgWords
    };

    // ═══ STAGE 2: BRIEF ══════════════════════════════════════════════════════
    console.log(`[pipeline] Stage 2/5: BRIEF — generating content brief`);
    let brief = null;
    if (geminiKey) {
      const briefPrompt = `Create a professional content brief for the keyword "${keyword}". Base it on this research data:

COMPETITORS: ${competitors.length} pages analyzed, avg ${avgWords} words
TOP H2 HEADINGS USED: ${[...new Set(competitors.flatMap(c => c.h2_count ? ['Example H2'] : []))].join(', ')}
PEOPLE ALSO ASK: ${paa.map(q => q.question).join('; ')}
RELATED SEARCHES: ${related.join(', ')}

Generate JSON:
{
  "target_word_count": ${Math.round(avgWords * 1.15)},
  "title": "SEO-optimized title for ${keyword}",
  "meta_description": "Compelling 155-char meta description",
  "h1": "Main H1 heading",
  "h2_outline": ["H2 One: topic", "H2 Two: topic", "H2 Three: topic", "H2 Four: topic", "H2 Five: topic"],
  "topics_to_cover": ["topic 1", "topic 2", "topic 3"],
  "paa_to_answer": ["${paa[0]?.question || 'Question 1'}"],
  "statistics_to_find": ["relevant statistic 1", "relevant statistic 2"],
  "schema_types": ["Article", "FAQPage"],
  "voice_search_answer": "30-50 word natural language answer",
  "internal_linking": ["suggested internal page to link"],
  "cta": "Call-to-action for the end"
}`;
      try {
        const gemResult = await callGeminiWithFallback(geminiKey, {
          contents: [{ parts: [{ text: briefPrompt }] }],
          generationConfig: { temperature: 0.3, maxOutputTokens: 4096, responseMimeType: 'application/json' }
        });
        if (gemResult.ok) {
          const raw = gemResult.data?.candidates?.[0]?.content?.parts?.[0]?.text || '';
          brief = extractJsonFromText(raw);
          if (!brief) {
            console.warn('[extractJsonFromText] null result — Pipeline brief (stage 2): AI returned truncated or invalid JSON — try again.');
            return res.status(502).json({ success: false, error: 'Pipeline brief (stage 2): AI returned truncated or invalid JSON — try again.' });
          }
        }
      } catch(e) { console.warn('[pipeline] Brief generation failed:', e.message); }
    }

    pipeline.stages.brief = {
      status: brief ? 'complete' : 'failed',
      brief: brief || { error: 'Brief generation failed — AI key may be missing' }
    };

    // ═══ STAGE 3: DRAFT ══════════════════════════════════════════════════════
    console.log(`[pipeline] Stage 3/5: DRAFT — writing content`);
    let draft = null;
    if (claudeKey && brief) {
      const draftPrompt = `Write a complete, optimized article for the keyword "${keyword}".

CONTENT BRIEF:
- Target: ${brief.target_word_count || avgWords} words
- Title: ${brief.title || keyword}
- H1: ${brief.h1 || keyword}
- Outline: ${(brief.h2_outline || []).join(' → ')}
- Topics: ${(brief.topics_to_cover || []).join(', ')}
- Answer these PAA questions: ${(brief.paa_to_answer || []).join('; ')}
- Include statistics: ${(brief.statistics_to_find || []).join(', ')}
- Schema: ${(brief.schema_types || []).join(', ')}
- CTA: ${brief.cta || 'Subscribe/learn more'}

PEOPLE ALSO ASK TO ANSWER:
${paa.map(q => 'Q: ' + q.question).join('\n')}

COMPETITOR INSIGHTS:
${competitors.slice(0, 3).map(c => '- ' + c.title + ' (' + c.word_count + ' words)').join('\n')}

REQUIREMENTS:
1. Write in a professional, engaging tone
2. Use H2 and H3 headings throughout
3. Include bullet points and numbered lists where helpful
4. Add a FAQ section at the end with 5+ questions
5. Include the voice search answer as a clear definition early in the content
6. Add a strong CTA at the end
7. Mark where statistics should go with [STAT: description]
8. Output as clean HTML (headings, paragraphs, lists only — no CSS, no scripts)`;

      try {
        const draftResult = await callClaude(claudeKey, {
          model: 'claude-sonnet-4-6',
          max_tokens: 8192,
          messages: [{ role: 'user', content: draftPrompt }]
        });
        if (draftResult.ok) {
          draft = draftResult.data?.content?.[0]?.text || draftResult.data?.completion || '';
        }
      } catch(e) { console.warn('[pipeline] Draft generation failed:', e.message); }
    }

    pipeline.stages.draft = {
      status: draft ? 'complete' : 'failed',
      word_count: draft ? draft.replace(/<[^>]+>/g, ' ').trim().split(/\s+/).length : 0,
      content: draft || null,
      error: draft ? null : 'Draft generation failed — Claude key may be missing'
    };

    // ═══ STAGE 4: REVIEW ═════════════════════════════════════════════════════
    console.log(`[pipeline] Stage 4/5: REVIEW — scoring draft`);
    let review = null;
    if (draft) {
      try {
        const scoreResult = await browserScanHtml(draft, url || keyword);
        if (scoreResult) {
          review = {
            score: scoreResult.score,
            metrics: scoreResult.metrics,
            recommendations: scoreResult.recommendations,
            quality: scoreResult.quality,
            word_count: scoreResult.content_stats?.total_words || pipeline.stages.draft.word_count,
            grade: scoreResult.score >= 90 ? 'A+' : scoreResult.score >= 75 ? 'A' : scoreResult.score >= 60 ? 'B' : scoreResult.score >= 40 ? 'C' : 'D'
          };
        }
      } catch(e) { console.warn('[pipeline] Review scoring failed:', e.message); }
    }

    pipeline.stages.review = {
      status: review ? 'complete' : (draft ? 'partial' : 'skipped'),
      score: review?.score || null,
      grade: review?.grade || null,
      metrics: review?.metrics || null,
      recommendations: review?.recommendations || null,
      word_count: review?.word_count || pipeline.stages.draft.word_count || 0,
      gaps: brief && review ? [
        review.word_count < (brief.target_word_count * 0.9) ? `Word count low: ${review.word_count} vs target ${brief.target_word_count}` : null,
        !review.metrics?.faq ? 'Missing FAQ section' : null,
        review.score < 70 ? `Score needs improvement: ${review.score}/100` : null
      ].filter(Boolean) : []
    };

    // ═══ STAGE 5: PUBLISH ════════════════════════════════════════════════════
    console.log(`[pipeline] Stage 5/5: PUBLISH — ready`);
    pipeline.stages.publish = {
      status: 'ready',
      html_content: draft,
      title: brief?.title || keyword,
      meta_description: brief?.meta_description || '',
      h1: brief?.h1 || keyword,
      schema_types: brief?.schema_types || ['Article'],
      can_publish: !!draft,
      publish_methods: ['webhook', 'copy_html']
    };

    pipeline.completed_at = new Date().toISOString();
    res.json({ success: true, pipeline });

  } catch(e) {
    console.error('[pipeline] Error:', e.message);
    pipeline.error = e.message;
    res.status(500).json({ success: false, error: e.message, pipeline });
  }
});

const resolveGeminiKey = (req) => {
  const code      = req.engineUser && req.engineUser.code ? req.engineUser.code : null;
  const codeKey   = code ? code.gemini_key : null;          // Ottmar pre-filled per engine code
  const headerKey = req.headers['x-gemini-key'] || null;   // Client entered in sidebar
  const mode      = code ? (code.api_key_mode || (code.use_platform_keys ? 'platform' : 'byok')) : 'platform';
  const envKey    = process.env.GEMINI_API_KEY;

  // If Ottmar pre-filled a Gemini key for this engine code — always use it
  if (codeKey) { return codeKey; }

  if (mode === 'byok') {
    return headerKey || null; // BYOK: client key only
  }
  return envKey || null; // Platform: Ottmar's Railway key
};
const resolveClaudeKey = (req) => {
  const code       = req.engineUser && req.engineUser.code ? req.engineUser.code : null;
  const codeKey    = code ? code.claude_key : null;           // Ottmar pre-filled per engine code
  const headerKey  = req.headers['x-claude-key'] || null;    // Client entered in Content Engine sidebar
  const mode       = code ? (code.api_key_mode || (code.use_platform_keys ? 'platform' : 'byok')) : 'platform';
  const envKey     = process.env.ANTHROPIC_API_KEY;

  // If Ottmar pre-filled a Claude key for this engine code — always use it
  if (codeKey) { console.log('[keys] Claude: engine-code key'); return codeKey; }

  if (mode === 'byok') {
    // BYOK: client must provide their own key via sidebar or header
    if (headerKey) { console.log('[keys] Claude: BYOK client header key'); return headerKey; }
    console.log('[keys] Claude: BYOK mode — no key available');
    return null;
  }

  // Platform mode: use Ottmar's Railway key
  if (envKey) { console.log('[keys] Claude: platform env key'); return envKey; }
  return null;
};
const resolveSerpapiKey = (req) => {
  const headerKey = req.headers['x-serpapi-key'];
  const codeKey = req.engineUser && req.engineUser.code ? req.engineUser.code.serpapi_key : null;
  const envKey = process.env.SERPAPI_KEY || process.env.SERPER_API_KEY; // support both names

  if (headerKey) { console.log('[keys] SerpAPI: using header key'); return headerKey; }
  if (codeKey) { console.log('[keys] SerpAPI: using per-code key'); return codeKey; }
  if (envKey) { console.log('[keys] SerpAPI: using env key (' + (process.env.SERPAPI_KEY ? 'SERPAPI_KEY' : 'SERPER_API_KEY') + ')'); return envKey; }
  console.log('[keys] SerpAPI: NO KEY FOUND — set SERPAPI_KEY or SERPER_API_KEY in Railway');
  return null;
};
const resolveYouApiKey       = (req) => req.headers['x-you-api-key']        || process.env.YOU_API_KEY;
const resolvePerplexityKey   = (req) => req.headers['x-perplexity-key']     || process.env.PERPLEXITY_API_KEY;

// ── CREDITS SYSTEM ────────────────────────────────────────────────────────────
// Only charged when use_platform_keys=true AND platform_credits is not NULL
const CREDIT_COSTS = {
  'research':        3,
  'brief':           2,
  'write':          10,
  'analyse-rewrite': 2,
  'execute-rewrite': 8,
  'stats-study':     2,
  'bulk-create':     5,
  'news-generate':   4,   // AI news article generation per batch (up to 3 articles)
};


async function spendCredits(codeId, action) {
  const cost = CREDIT_COSTS[action] || 1;
  try {
    const r = await pool.query(
      `UPDATE engine_access_codes SET credits_used = credits_used + $1 WHERE id = $2 AND use_platform_keys = TRUE AND (platform_credits IS NULL OR platform_credits >= credits_used + $1) RETURNING id, platform_credits, credits_used`,
      [cost, codeId]
    );
    if (!r.rows.length) {
      return { ok: false, error: 'Insufficient platform credits' };
    }
    const row = r.rows[0];
    const creditsLeft = row.platform_credits !== null ? (row.platform_credits - row.credits_used) : null;
    // Log the credit spend
    await pool.query(
      `INSERT INTO credit_log (code_id, action, credits_spent, detail) VALUES ($1, $2, $3, $4)`,
      [codeId, action, cost, `Spent ${cost} credits for ${action}`]
    ).catch(() => {});
    return { ok: true, cost: cost, credits_left: creditsLeft };
  } catch (e) {
    console.error('spendCredits error:', e.message);
    return { ok: false, error: e.message };
  }
}

// extractJsonFromText defined above — duplicate removed

// Helper: safely parse profile.locations from PostgreSQL json_agg (may be string or array)
function safeProfileLocations(profile) {
  if (!profile) return [];
  if (typeof profile.locations === 'string') {
    try { profile.locations = JSON.parse(profile.locations); } catch(e) { profile.locations = []; }
  }
  if (!Array.isArray(profile.locations)) profile.locations = [];
  return profile.locations;
}

function requireCredits(action) {
  return async (req, res, next) => {
    try {
      const eu = req.engineUser;
      if (!eu) return next();
      if (eu.isAdmin) return next();
      if (!eu.code) return next();
      // ── BYOK users pass through (they pay Google/Anthropic directly) ──
      if (eu.code.api_key_mode === 'byok') return next();
      // ── Platform key users: check monthly cost limit ──
      // Reset monthly cost if needed
      const now = new Date();
      const resetAt = eu.code.cost_reset_at ? new Date(eu.code.cost_reset_at) : null;
      if (!resetAt || now.getMonth() !== resetAt.getMonth() || now.getFullYear() !== resetAt.getFullYear()) {
        await pool.query(`UPDATE engine_access_codes SET monthly_cost_used=0, cost_reset_at=NOW() WHERE id=$1`, [eu.codeId]).catch(()=>{});
        eu.code.monthly_cost_used = 0;
      }
      const limit = parseFloat(eu.code.monthly_cost_limit) || 5;
      const used = parseFloat(eu.code.monthly_cost_used) || 0;
      if (used >= limit) {
        return res.status(402).json({
          success: false,
          error: `Budget exhausted: €${used.toFixed(2)} used of €${limit.toFixed(2)} limit. Contact admin to top up.`,
          code: 'COST_LIMIT_REACHED',
          used: used,
          limit: limit
        });
      }
      req.monthlyLimit = limit;
      req.monthlyUsed = used;
      next();
    } catch (e) {
      console.error('[requireApiAccess]', e);
      return res.status(500).json({ success: false, error: 'API access check failed: ' + e.message });
    }
  };
}

// ── API Cost Estimation ─────────────────────────────────────
const COST_RATES = {
  'gemini-2.5-flash': { input: 0.075e-6, output: 0.30e-6 },
  'gemini-2.5-flash-lite': { input: 0.075e-6, output: 0.15e-6 },
  'gemini-2.0-flash': { input: 0.075e-6, output: 0.30e-6 },
  'gemini-1.5-flash-001': { input: 0.075e-6, output: 0.30e-6 },
  'claude-sonnet-4-6': { input: 3.00e-6, output: 15.00e-6 },
  'claude-haiku-4-5-20251001': { input: 1.00e-6, output: 5.00e-6 },
  'perplexity-sonar':     { input: 1.00e-6, output: 1.00e-6 },
  'perplexity-sonar-pro': { input: 3.00e-6, output: 15.00e-6 },
};
function estimateApiCost(model, inputTokens, outputTokens) {
  const rate = COST_RATES[model] || COST_RATES['gemini-2.5-flash'];
  return ((inputTokens || 0) * rate.input) + ((outputTokens || 0) * rate.output);
}
async function trackApiCost(codeId, action, model, inputTokens, outputTokens, detail) {
  try {
    const cost = estimateApiCost(model, inputTokens, outputTokens);
    await pool.query(`INSERT INTO api_cost_log (code_id, action, model, input_tokens, output_tokens, estimated_cost, detail) VALUES ($1,$2,$3,$4,$5,$6,$7)`, [codeId, action, model, inputTokens || 0, outputTokens || 0, cost, detail || '']);
    await pool.query(`UPDATE engine_access_codes SET monthly_cost_used = COALESCE(monthly_cost_used,0) + $1 WHERE id=$2`, [cost, codeId]);
    return { ok: true, cost };
  } catch (e) {
    console.error('[trackApiCost] failed:', e.message);
    return { ok: false, cost: 0 };
  }
}

