// ── Async Research Jobs ──────────────────────────────────────
const _researchJobs = new Map(); // jobId -> {status, result, error}

app.post('/api/content/research', verifyEngineAccess, requireCredits('research'), async (req, res) => {
  try {
    const { profile_id, seed_keyword } = req.body;
    if (!profile_id || !seed_keyword) return res.status(400).json({ success: false, error: 'profile_id and seed_keyword required' });

    // Mark any old stuck 'researching' jobs for this profile+keyword as abandoned
    // This lets users retry without being blocked by previous stuck jobs
    const abandonedR = await pool.query(
      `UPDATE content_jobs SET status='error', error_message='Abandoned — user started new research' 
       WHERE profile_id=$1 AND seed_keyword=$2 AND status='researching' 
       RETURNING id`,
      [profile_id, seed_keyword]
    );
    if (abandonedR.rows.length > 0) {
      console.log(`[research] abandoned ${abandonedR.rows.length} stuck job(s) for "${seed_keyword}"`);
      abandonedR.rows.forEach(r => _researchJobs.set(r.id, { status: 'error', error: 'Abandoned' }));
    }

    // Create job immediately, return jobId for polling
    const jobR = await pool.query(
      `INSERT INTO content_jobs (profile_id, seed_keyword, status, keyword_data, brief, created_at, updated_at)
       VALUES ($1,$2,'researching','{}','{}',NOW(),NOW()) RETURNING *`,
      [profile_id, seed_keyword]
    );
    const job = jobR.rows[0];
    const jobId = job.id;

    // Return job ID immediately — frontend will poll
    res.json({ success: true, job_id: jobId, job: { id: jobId, status: 'researching', seed_keyword }, message: 'Research started — poll for results' });

    // ── Run research in background ──
    _runResearchJob(jobId, profile_id, seed_keyword).catch(err => {
      console.error(`[research job ${jobId}] crashed:`, err.message);
      _researchJobs.set(jobId, { status: 'error', error: err.message });
      pool.query(`UPDATE content_jobs SET status='error', error_message=$1 WHERE id=$2`, [err.message, jobId]).catch(()=>{});
    });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// Poll endpoint for research results
app.get('/api/content/research/:jobId', verifyEngineAccess, async (req, res) => {
  try {
    const jobR = await pool.query(`SELECT * FROM content_jobs WHERE id=$1`, [req.params.jobId]);
    if (!jobR.rows.length) return res.status(404).json({ success: false, error: 'Job not found' });
    const job = jobR.rows[0];
    const inMemory = _researchJobs.get(parseInt(req.params.jobId));

    // Safety check: if researching for more than 5 minutes, treat as error
    if (job.status === 'researching' && job.created_at) {
      const ageMs = Date.now() - new Date(job.created_at).getTime();
      if (ageMs > 300000) { // 5 minutes
        await pool.query(`UPDATE content_jobs SET status='error', error_message=$1 WHERE id=$2`, ['Research timed out after 5 minutes', job.id]).catch(()=>{});
        return res.json({ success: false, status: 'error', error: 'Research timed out after 5 minutes — please try again' });
      }
    }

    if (job.status === 'completed') {
      return res.json({ success: true, status: 'completed', job: job, research: job.keyword_data });
    }
    if (job.status === 'error' || (inMemory && inMemory.status === 'error')) {
      return res.json({ success: false, status: 'error', error: job.error_message || (inMemory && inMemory.error) || 'Unknown error' });
    }
    // Still researching — include step + message for progress display
    res.json({ success: true, status: 'researching', 
      step: inMemory?.step || 'researching',
      message: inMemory?.message || 'Researching...',
      job: { id: job.id, status: 'researching', seed_keyword: job.seed_keyword } });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

async function _runResearchJob(jobId, profile_id, seed_keyword) {
  console.log(`[research job ${jobId}] starting for "${seed_keyword}"`);
  _researchJobs.set(jobId, { status: 'researching', step: 'init', message: 'Starting research...' });

  // Safety timeout — 2.5 minutes max for entire job
  const safetyTimeout = setTimeout(async () => {
    console.error(`[research job ${jobId}] SAFETY TIMEOUT after 2.5 min`);
    _researchJobs.set(jobId, { status: 'error', error: 'Timed out', step: 'timeout' });
    await pool.query(`UPDATE content_jobs SET status='error', error_message=$1 WHERE id=$2`, ['Research timed out', jobId]).catch(()=>{});
  }, 150000);

  try {
    _researchJobs.set(jobId, { status: 'researching', step: 'profile', message: 'Loading profile...' });
    const profileR = await pool.query(`SELECT cp.*, COALESCE(json_agg(cl ORDER BY cl.sort_order) FILTER (WHERE cl.id IS NOT NULL), '[]') AS locations FROM content_profiles cp LEFT JOIN content_locations cl ON cl.profile_id=cp.id WHERE cp.id=$1 GROUP BY cp.id`, [profile_id]);
    if (!profileR.rows.length) throw new Error('Profile not found');
    const profile = profileR.rows[0];
    safeProfileLocations(profile);
    const codeId = profile.owner_code_id || null;
    const geminiKey = process.env.GEMINI_API_KEY;
    if (!geminiKey) throw new Error('GEMINI_API_KEY not set');

    // Fetch sitemap (5s timeout)
    _researchJobs.set(jobId, { status: 'researching', step: 'sitemap', message: 'Fetching sitemap...' });
    let sitemapLinks = [];
    try {
      if (profile && profile.sitemap_url) {
        const ctrl = new AbortController(); const t = setTimeout(()=>ctrl.abort(),5000);
        const r = await fetch(profile.sitemap_url, { headers:{'User-Agent':'CSBot/1.0'}, signal:ctrl.signal });
        clearTimeout(t);
        const txt = await r.text();
        sitemapLinks = (txt.match(/<loc>(.*?)<\/loc>/g)||[]).map(m=>m.replace(/<\/?loc>/g,'').trim()).filter(u=>u).slice(0,20);
      }
    } catch(e) {}

    // STEP 1: REAL WEB SEARCH for statistics
    _researchJobs.set(jobId, { status: 'researching', step: 'web_search', message: 'Searching web for real statistics...' });
    const locs = (profile.locations||[]).map(l=>l.location_value).join(', ') || profile.geo_focus || '';
    const searchQueries = [
      `${seed_keyword} ${profile.niche} statistics 2024 2025 2026`,
      `${profile.niche} industry report ${locs} cost price data`,
      `${seed_keyword} EPA government data statistics`,
      `${profile.niche} market size revenue 2024 2025`
    ];
    console.log(`[research job ${jobId}] searching web: ${searchQueries.join(' | ')}`);
    const webResults = await doWebSearch(searchQueries);
    console.log(`[research job ${jobId}] web search: ${webResults.length} results`);

    // Format web results for Gemini context
    const webContext = webResults.length > 0
      ? webResults.slice(0, 15).map((r, i) =>
          `SOURCE ${i+1}: ${r.title}\nURL: ${r.url}\nSNIPPET: ${r.snippet}\n---`
        ).join('\n')
      : 'No web results found. Use your training knowledge for statistics.';

    // STEP 2: Gemini call WITH real web data
    _researchJobs.set(jobId, { status: 'researching', step: 'ai_analysis', message: `Analyzing ${webResults.length} sources with AI...` });
    const year = new Date().getFullYear();
    const bi = (typeof profile.business_info === 'string' ? JSON.parse(profile.business_info || '{}') : profile.business_info) || {};

    const prompt = `You are an expert SEO researcher. Analyze these REAL web search results about "${seed_keyword}" for a ${profile.niche} business in ${locs}.

REAL WEB SEARCH RESULTS:
${webContext}

Your task: Extract 8-12 REAL statistics from the search results above. For each stat, use the EXACT source URL provided. If the web results don't have enough stats, supplement with your knowledge but ONLY use real, verifiable data.

CRITICAL: Every statistic MUST have:
- A specific number (not vague ranges like "many" or "some")
- A real source name and year
- A real URL (from the search results above, or a well-known .gov/.edu/trade site)

Return ONLY this JSON (fill every field with real, sourced content):
{
  "primary_keyword": "exact keyword",
  "secondary_keywords": ["kw1","kw2","kw3","kw4","kw5"],
  "lsi_keywords": ["related1","related2","related3"],
  "long_tail_variants": ["long tail 1","long tail 2","long tail 3"],
  "search_intent": "commercial",
  "intent_analysis": "What the searcher wants and why",
  "recommended_title": "SEO Title with ${year} and Number: Benefit",
  "title_alternatives": ["Alt 1","Alt 2"],
  "recommended_h2s": ["Detailed H2 One","Detailed H2 Two","Detailed H2 Three","Detailed H2 Four","Detailed H2 Five","Detailed H2 Six","Detailed H2 Seven"],
  "target_word_count": 2500,
  "competitor_analysis": [
    {"url":"example.com","title":"Their Title","strengths":"What they do well","weaknesses":"Gap to exploit","h2_structure":["Their H1","Their H2"],"word_count_estimate":2000}
  ],
  "content_gaps": ["gap 1","gap 2","gap 3"],
  "paa_questions": [
    {"question":"Question?","direct_answer":"50 word answer","snippet_format":"paragraph"}
  ],
  "original_statistics": [
    {"stat": "Specific number/fact with context", "source": "Real source name and year", "url": "https://real-source-url.com"},
    {"stat": "Another verified number", "source": "Source Name, Year", "url": "https://source.com"}
  ],
  "service_area_external_links": ${JSON.stringify(bi.location_links || {})},
  "bofu_ctas": ["Book a Free Consultation","Get a Quote Today","Call Now: ${profile.phone || 'us'}"],
  "ai_overview_tips": ["Direct answer first","FAQ schema","HowTo markup","Speakable schema"],
  "voice_search_queries": ["How do I ${seed_keyword}","What is the best ${seed_keyword} near me"],
  "voice_search_optimization": "Use natural language, answer in 30-50 words, include geo terms"
}`;

    console.log(`[research job ${jobId}] calling Gemini with ${webResults.length} web results...`);
    const gemResult = await callGeminiWithFallback(
      geminiKey,
      { contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0.2, maxOutputTokens: 4096 } }
    );
    console.log(`[research job ${jobId}] Gemini: ok=${gemResult.ok} status=${gemResult.status}`);
    if (!gemResult.ok) throw new Error('Gemini failed: ' + (gemResult.errorMessage || gemResult.status));

    const rawText = gemResult.data?.candidates?.[0]?.content?.parts?.[0]?.text || '';
    if (!rawText) throw new Error('Empty response');

    let keywordData = extractJsonFromText(rawText);
    if (!keywordData) {
      console.warn('[extractJsonFromText] null result — Keyword research: AI returned truncated or invalid JSON — try again.');
      return res.status(502).json({ success: false, error: 'Keyword research: AI returned truncated or invalid JSON — try again.' });
    }
    console.log(`[research job ${jobId}] parsed: pk=${keywordData.primary_keyword||'N/A'}`);

    // Track cost
    if (codeId) {
      const usage = gemResult.data?.usageMetadata || {};
      await trackApiCost(codeId, 'research', gemResult.modelUsed||GEMINI_MODEL, usage.promptTokenCount||0, usage.candidatesTokenCount||Math.round(rawText.length/4), `Research: ${seed_keyword}`);
    }

    // Save as COMPLETED immediately
    _researchJobs.set(jobId, { status: 'researching', step: 'saving', message: 'Saving research results...' });
    await pool.query(
      `UPDATE content_jobs SET status='completed', completed_at=NOW(), keyword_data=$1 WHERE id=$2`,
      [JSON.stringify(keywordData), jobId]
    );
    _researchJobs.set(jobId, { status: 'completed', result: keywordData, step: 'done', message: 'Research complete!' });
    clearTimeout(safetyTimeout);
    console.log(`[research job ${jobId}] DONE`);

  } catch(e) {
    console.error(`[research job ${jobId}] ERROR:`, e.message);
    clearTimeout(safetyTimeout);
    await pool.query(`UPDATE content_jobs SET status='error', error_message=$1 WHERE id=$2`, [e.message, jobId]).catch(()=>{});
    _researchJobs.set(jobId, { status: 'error', error: e.message, step: 'error', message: 'Error: ' + e.message });
  }
}

// ── REAL WEB SEARCH for research ──────────────────────────────
// Searches the web and returns raw results with URLs for stat extraction
async function doWebSearch(queries) {
  const allResults = [];
  for (const query of queries.slice(0, 4)) { // max 4 queries to stay within time
    try {
      // Try SerpAPI if key is available
      const serpKey = process.env.SERPAPI_KEY;
      if (serpKey) {
        const params = new URLSearchParams({
          engine: 'google', q: query, api_key: serpKey,
          num: '5', hl: 'en', gl: 'us'
        });
        const ctrl = new AbortController(); const t = setTimeout(()=>ctrl.abort(),8000);
        const r = await fetch(`https://serpapi.com/search?${params}`, { signal: ctrl.signal });
        clearTimeout(t);
        const data = await r.json();
        const snippets = (data.organic_results||[]).map(o => ({
          title: o.title||'', snippet: o.snippet||'', url: o.link||'', source: 'serpapi'
        }));
        allResults.push(...snippets);
        continue;
      }
      // Fallback: try DuckDuckGo instant answer API (no key needed)
      const ddgUrl = `https://html.duckduckgo.com/html/?q=${encodeURIComponent(query)}`;
      const ctrl2 = new AbortController(); const t2 = setTimeout(()=>ctrl2.abort(),8000);
      const r = await fetch(ddgUrl, {
        headers: { 'User-Agent': 'Mozilla/5.0 (compatible; ResearchBot/1.0)' },
        signal: ctrl2.signal
      });
      clearTimeout(t2);
      const html = await r.text();
      // Extract results from DuckDuckGo HTML
      const resultRegex = /<a[^>]*class="result__a"[^>]*href="([^"]*)">(.*?)<\/a>.*?<a[^>]*class="result__snippet"[^>]*>(.*?)<\/a>/gs;
      let match;
      while ((match = resultRegex.exec(html)) !== null && allResults.length < 20) {
        const url = match[1].replace(/^\/\/duckduckgo.com\/l\/\?uddg=/, '').replace(/&rut=.*$/, '');
        const title = match[2].replace(/<[^>]*>/g, '').trim();
        const snippet = match[3].replace(/<[^>]*>/g, '').trim();
        if (url && title && snippet) {
          try { allResults.push({ title, snippet, url: decodeURIComponent(url), source: 'ddg' }); } catch(e) {}
        }
      }
    } catch(e) {
      console.log(`[web search] query "${query}" failed:`, e.message);
    }
  }
  return allResults;
}

// ── Helpers used by endpoints ─────────────────────────────────
function safeParse(v, fallback) {
  if (!v) return fallback;
  if (typeof v === 'object') return v;
  try { return JSON.parse(v); } catch(e) { return fallback; }
}

// Validate that a brief has real content (not placeholders or empty arrays)
function validateBrief(brief, seedKeyword) {
  const errors = [];
  if (!brief.title || brief.title.trim().length < 10) errors.push('title too short or missing');
  if (!brief.structure || !Array.isArray(brief.structure) || brief.structure.length < 3) errors.push('needs at least 3 H2 headings');
  if (!brief.bofu_ctas || !Array.isArray(brief.bofu_ctas) || brief.bofu_ctas.length === 0) errors.push('missing BOFU CTAs');
  if (!brief.ai_overview_tips || !Array.isArray(brief.ai_overview_tips) || brief.ai_overview_tips.length === 0) errors.push('missing AI Overview tips');
  if (!brief.voice_search_queries || !Array.isArray(brief.voice_search_queries) || brief.voice_search_queries.length === 0) errors.push('missing voice search queries');

  // Check for placeholder text
  const placeholderPatterns = ['H2 1', 'H2 2', 'Hey Google', 'Alexa', 'Siri', 'PLACEHOLDER', 'example'];
  const allText = JSON.stringify(brief).toLowerCase();
  placeholderPatterns.forEach(p => {
    if (allText.includes(p.toLowerCase())) errors.push(`contains placeholder text: "${p}"`);
  });

  return {
    isValid: errors.length === 0,
    errors: errors,
    missingFields: errors
  };
}

