            lines.push((i+1) + '. [' + pri + '] ' + (p.title || p.t || '') + ((p.system||p.sys) ? ' (' + (p.system||p.sys) + ')' : ''));
            if (p.action || p.passage) lines.push('   ' + (p.action || p.passage));
