// ── GENERATE COMMENTS ────────────────────────────────────────────────────
async function generateBoostComments(postText, clientName, tone, claudeKey) {
  const prompt = `Write ONE excellent LinkedIn comment for this post. It should work for anyone — regardless of their background or industry.

Post: "${postText.substring(0,800)}"
${tone ? 'Tone/language hint: ' + tone : ''}

Rules:
- ONE comment only. Make it genuinely good.
- Adds a real insight, observation, or question — not just agreement.
- 2-3 sentences. No more.
- Sounds like a thoughtful professional, not a bot.
- NEVER start with: "Great post", "Love this", "This resonates", "So true", "Absolutely", "Spot on", "That's exactly"
- No hashtags. No emojis. No generic openers.
- Same language as the post.
- Universal — anyone in any role can post this without it feeling off.

Return ONLY a valid JSON array with exactly 1 string, no markdown:
["your comment here"]`;

  const r = await fetch('https://api.anthropic.com/v1/messages', {
    method:'POST',
    headers:{'Content-Type':'application/json','x-api-key':claudeKey,'anthropic-version':'2023-06-01'},
    body: JSON.stringify({model:'claude-sonnet-4-6',max_tokens:400,messages:[{role:'user',content:prompt}]})
  });
  const json = await r.json();
  const raw = json.content?.[0]?.text?.trim()||'';
  const match = raw.match(/\[[\s\S]*\]/);
  return JSON.parse(match ? match[0] : raw);
}

// ── GET USER ─────────────────────────────────────────────────────────────
async function getBoostUser(token, ip) {
  const r = await pool.query('SELECT * FROM boost_users WHERE token=$1 AND active=TRUE AND (expires_at IS NULL OR expires_at > NOW())',[token]);
  if (!r.rows.length) return null;
  const u = r.rows[0];
  if (!u.first_ip && ip) await pool.query('UPDATE boost_users SET first_ip=$1,last_seen_at=NOW() WHERE id=$2',[ip,u.id]);
  else await pool.query('UPDATE boost_users SET last_seen_at=NOW() WHERE id=$1',[u.id]);
  if (u.week_reset_at && new Date(u.week_reset_at) < new Date()) {
    await pool.query('UPDATE boost_users SET sessions_week=0,week_reset_at=NOW()+INTERVAL \'7 days\' WHERE id=$1',[u.id]);
    u.sessions_week = 0;
  }
  return u;
}

const ADMIN_TOKENS = ['ottmar-admin-2026', 'ottmarJGfrancisca-boost-admin-9274', process.env.ADMIN_TOKEN].filter(Boolean);
function isAdmin(u) { return u && (u.tier==='admin' || ADMIN_TOKENS.includes(u.token)); }

function checkAdminToken(req, res) {
  const token = req.body?.adminToken || req.query?.adminToken;
  if (!ADMIN_TOKENS.includes(token)) {
    res.status(401).json({ error: 'Unauthorized' });
    return false;
  }
  return true;
}



// ── NOTIFY ALL USERS WITH CALLMEBOT ──────────────────────────────────────
async function notifyAllUsers(message) {
  if (!pool) return;
  try {
    const r = await pool.query(
      "SELECT whatsapp, callmebot_key FROM boost_users WHERE active=TRUE AND callmebot_key IS NOT NULL AND callmebot_key != ''"
    );
    console.log(`[Notify] Sending to ${r.rows.length} users with CallMeBot`);
    for (const user of r.rows) {
      try {
        const phone = (user.whatsapp||'').replace(/[^0-9]/g,'');
        if (!phone) continue;
        const url = `https://api.callmebot.com/whatsapp.php?phone=${phone}&text=${encodeURIComponent(message)}&apikey=${user.callmebot_key}`;
        await fetch(url);
        await new Promise(r => setTimeout(r, 500)); // 500ms between calls
      } catch(e) { console.warn('[Notify] User notify failed:', e.message); }
    }
  } catch(e) { console.warn('[Notify] notifyAllUsers error:', e.message); }
}

// ── WHATSAPP NOTIFICATION (CallMeBot) ────────────────────────────────────
async function notifyOttmarWhatsApp(message) {
  const phone  = process.env.CALLMEBOT_PHONE;
  const apiKey = process.env.CALLMEBOT_KEY;
  if (!phone || !apiKey) return; // silently skip if not configured

  try {
    const url = `https://api.callmebot.com/whatsapp.php?phone=${phone}&text=${encodeURIComponent(message)}&apikey=${apiKey}`;
    await fetch(url);
    console.log('[Notify] WhatsApp sent to Ottmar');
  } catch(e) {
    console.warn('[Notify] WhatsApp failed:', e.message);
  }
}

